def regex_match(pattern: str, text: str) -> bool:
    n = len(pattern)
    i = 0

    def peek():
        return pattern[i] if i < n else None

    def consume():
        nonlocal i
        c = pattern[i]
        i += 1
        return c

    def parse_alt():
        nodes = [parse_concat()]
        while peek() == '|':
            consume()
            nodes.append(parse_concat())
        if len(nodes) == 1:
            return nodes[0]
        res = nodes[0]
        for node in nodes[1:]:
            res = ('alt', res, node)
        return res

    def parse_concat():
        nodes = []
        while peek() is not None and peek() not in ('|', ')'):
            nodes.append(parse_quant())
        return ('concat', tuple(nodes)) if nodes else ('empty',)

    def parse_quant():
        child = parse_atom()
        q = peek()
        if q == '*':
            consume()
            return ('star', child)
        elif q == '+':
            consume()
            return ('plus', child)
        elif q == '?':
            consume()
            return ('opt', child)
        return child

    def parse_atom():
        c = peek()
        if c == '(':
            consume()
            node = parse_alt()
            if peek() == ')':
