            return ('group', node)
        elif c == '[':
            consume()
            negated = False
            if peek() == '^':
                negated = True
                consume()
            chars = set()
            if peek() == ']':
                chars.add(']')
                consume()
            while peek() is not None and peek() != ']':
                if peek() == '\\' and i + 1 < n:
                    consume()
                    chars.add(consume())
                elif i + 2 < n and peek() + 1 == pattern[i + 2] and pattern[i + 1] == '-':
                    start_ch = consume()
                    consume()
                    end_ch = consume()
                    for ch in range(ord(start_ch), ord(end_ch) + 1):
                        chars.add(chr(ch))
                else:
                    chars.add(consume())
            if peek() == ']':
