            return memo[key]

        res = set()
        type_ = node[0]

        if type_ == 'empty':
            res = {start}
        elif type_ == 'lit':
            if start < len(text) and text[start] == node[1]:
                res = {start + 1}
        elif type_ == 'dot':
            if start < len(text):
                res = {start + 1}
        elif type_ == 'bracket':
            if start < len(text):
                c = text[start]
                chars, neg = node[1], node[2]
                if (c in chars) ^ neg:
                    res = {start + 1}
        elif type_ == 'group':
            res = match(node[1], start)
        elif type_ == 'alt':
            res = match(node[1], start) | match(node[2], start)
        elif type_ == 'concat':
            ends = {start}
            for child in node[1]:
                next_ends = set()
                for s in ends:
                    next_ends |= match(child, s)
                if not next_ends:
                    break
                ends = next_ends
            res = ends
        elif type_ == 'star':
            child = node[1]
            ends = {start}
            for s in range(start, len(text)):
