            ends.discard(start)
            res = ends
        elif type_ == 'opt':
            res = match(node[1], start) | {start}

        memo[key] = res
        return res

    final_ends = match(parsed, 0)
    return len(text) in final_ends

def regex_match(pattern: str, text: str) -> bool:
    pos = 0
    n_pat = len(pattern)
    n_txt = len(text)

    def parse_alt():
