        while pos < n_pat and pattern[pos] not in '|)':
            atom, quant = parse_atom()
            seq.append((atom, quant))
        return seq

    def parse_atom():
        nonlocal pos
        if pattern[pos] == '(':
            pos += 1
            atom = ('group', parse_alt())
            if pos < n_pat and pattern[pos] == ')':
                pos += 1
        elif pattern[pos] == '[':
            pos += 1
            neg = False
            chars = set()
            first = True
            while pos < n_pat and pattern[pos] != ']':
                if first and pattern[pos] == '^':
                    neg = True
                    first = False
                    pos += 1
                else:
                    if pos + 2 < n_pat and pattern[pos+1] == '-' and pattern[pos+2] != ']':
                        chars.update(range(ord(pattern[pos]), ord(pattern[pos+2]) + 1))
                        pos += 3
                    else:
                        chars.add(pattern[pos])
                        pos += 1
                    first = False
            if pos < n_pat and pattern[pos] == ']':
                pos += 1
            atom = ('bracket', chars, neg)
        elif pattern[pos] == '.':
            pos += 1
            atom = ('dot',)
        elif pattern[pos] == '\\':
            pos += 1
            atom = ('char', pattern[pos])
            pos += 1
        else:
            atom = ('char', pattern[pos])
            pos += 1

        quant = None
        if pos < n_pat and pattern[pos] in '*+?':
            quant = pattern[pos]
            pos += 1
        return atom, quant

    alts = parse_alt()
    memo = {}

    def match_seq(seq, t_idx):
        if (seq, t_idx) in memo:
            return memo[(seq, t_idx)]

        if not seq:
            res = t_idx == n_txt
            memo[(seq, t_idx)] = res
            return res

        atom, quant = seq[0]
        rest = seq[1:]
        res = False

        if quant is None:
            if t_idx < n_txt and matches_atom(atom, text[t_idx]) and match_seq(rest, t_idx + 1):
                res = True
        elif quant == '*':
            # Zero matches
