                        break
                    k += 1
        elif quant == '+':
            # One or more matches
            k = t_idx
            while k < n_txt and matches_atom(atom, text[k]):
                if match_seq(rest, k + 1):
                    res = True
                    break
                k += 1
        elif quant == '?':
            # Zero matches
            if match_seq(rest, t_idx):
