            return atom[1] == ch
        elif atom[0] == 'dot':
            return True
        elif atom[0] == 'bracket':
            _, chars, neg = atom
            return (ch in chars) ^ neg
        elif atom[0] == 'group':
            _, group_alts = atom
            # A group atom matches if any alternative matches the remaining text
            for g_alt in group_alts:
                if match_seq(g_alt, t_idx):
                    return True
            return False
        return False

    # We need to pass t_idx to matches_atom, so we redefine it inside match_seq or use a closure
    # Let's fix the scope issue by restructuring slightly
    memo = {}

    def match_seq(seq, t_idx):
        if (seq, t_idx) in memo:
            return memo[(seq, t_idx)]

