        def atom_matches(ch):
            if atom[0] == 'char':
                return atom[1] == ch
            elif atom[0] == 'dot':
                return True
            elif atom[0] == 'bracket':
                _, chars, neg = atom
                return (ch in chars) ^ neg
            elif atom[0] == 'group':
                _, group_alts = atom
                for g_alt in group_alts:
                    if match_seq(g_alt, t_idx):
                        return True
                return False
            return False

        if quant is None:
            if t_idx < n_txt and atom_matches(text[t_idx]) and match_seq(rest, t_idx + 1):
                res = True
        elif quant == '*':
            if match_seq(rest, t_idx):
                res = True
            else:
                k = t_idx
                while k < n_txt and atom_matches(text[k]):
                    if match_seq(seq, k + 1):
                        res = True
                        break
                    k += 1
        elif quant == '+':
            k = t_idx
            while k < n_txt and atom_matches(text[k]):
                if match_seq(rest, k + 1):
                    res = True
                    break
                k += 1
        elif quant == '?':
            if match_seq(rest, t_idx):
                res = True
            elif t_idx < n_txt and atom_matches(text[t_idx]) and match_seq(rest, t_idx + 1):
                res = True

        memo[(seq, t_idx)] = res
        return res

    return any(match_seq(alt, 0) for alt in alts)

def regex_match(pattern: str, text: str) -> bool:
    def parse(s, idx):
        alts = []
        while idx < len(s):
            atoms, idx = parse_alt(s, idx)
            alts.append(tuple(atoms))
            if idx < len(s) and s[idx] == '|':
                idx += 1
            else:
                break
        return alts, idx

    def parse_alt(s, idx):
        atoms = []
        while idx < len(s):
            atom, idx = parse_atom(s, idx)
            quant = None
            if idx < len(s) and s[idx] in '*+?':
                quant = s[idx]
                idx += 1
            atoms.append((atom, quant))
        return atoms, idx

    def parse_atom(s, idx):
        if idx >= len(s): return None, idx
        ch = s[idx]
        if ch == '\\':
            idx += 2
            return ('LIT', s[idx-1]), idx
        elif ch == '[':
            idx += 1
            neg = False
            if idx < len(s) and s[idx] == '^':
                neg = True
                idx += 1
            chars = set()
            while idx < len(s) and s[idx] != ']':
                if idx + 2 < len(s) and s[idx+1] == '-':
                    start, end = s[idx], s[idx+2]
                    for c in range(ord(start), ord(end)+1):
                        chars.add(chr(c))
                    idx += 3
                else:
                    chars.add(s[idx])
                    idx += 1
            if idx < len(s): idx += 1
            return ('CLASS', frozenset(chars), neg), idx
        elif ch == '.':
            return ('DOT',), idx + 1
        elif ch == '(':
            idx += 1
            g_alts, idx = parse(s, idx)
            if idx < len(s) and s[idx] == ')': idx += 1
            return ('GROUP', tuple(g_alts)), idx
        else:
            return ('LIT', ch), idx + 1

    alts, _ = parse(pattern, 0)
    m = len(text)
    memo = {}

    def match_alt(atoms, j):
        key = (atoms, j)
        if key in memo: return memo[key]
        n = len(atoms)
        dp = [[False]*(m+1) for _ in range(n+1)]
        dp[n][m] = True
        for i in range(n-1, -1, -1):
            atom, quant = atoms[i]
            for j_idx in range(m-1, -1, -1):
                mc = False
                if atom[0] == 'LIT':
                    mc = text[j_idx] == atom[1]
                elif atom[0] == 'DOT':
                    mc = True
                elif atom[0] == 'CLASS':
                    mc = (text[j_idx] in atom[1]) ^ atom[2]
                elif atom[0] == 'GROUP':
                    for g_alt in atom[1]:
                        if match_alt(g_alt, j_idx):
                            mc = True
                            break
                if quant == '*':
                    dp[i][j_idx] = dp[i+1][j_idx] or (mc and dp[i][j_idx+1])
                elif quant == '+':
                    dp[i][j_idx] = mc and dp[i][j_idx+1]
                elif quant == '?':
                    dp[i][j_idx] = dp[i+1][j_idx] or (mc and dp[i][j_idx+1])
                else:
                    dp[i][j_idx] = mc and dp[i+1][j_idx+1]
        res = dp[0][0]
        memo[key] = res
        return res

    for atoms in alts:
        if match_alt(atoms, 0):
            return True
    return False

def regex_match(pattern: str, text: str) -> bool:
    if not pattern:
        return not text

    # Parse pattern into list of alternatives
    # Each alternative is a list of (atom, quantifier)
    # atom is one of: ('char', c), ('dot',), ('bracket', negated, chars_set), ('group', alts)
    alts = _parse_alts(pattern, 0, len(pattern))[0]

    # Try each top-level alternative
    for alt in alts:
        if _match(alt, 0, text, 0):
            return True
    return False

def _parse_alts(pattern, start, end):
    alts = [[]]
    i = start
    while i < end:
        if pattern[i] == '|':
            alts.append([])
            i += 1
        elif pattern[i] == ')':
            break
        else:
            atom, i = _parse_atom(pattern, i, end)
            quantifier = None
            if i < end and pattern[i] in '*+?':
                quantifier = pattern[i]
                i += 1
            alts[-1].append((atom, quantifier))
    return alts, i

def _parse_atom(pattern, start, end):
    if start >= end:
        raise ValueError("Unexpected end of pattern")
    if pattern[start] == '\\':
        if start + 1 < end:
            return ('char', pattern[start + 1]), start + 2
        else:
            raise ValueError("Invalid escape")
    elif pattern[start] == '.':
        return ('dot',), start + 1
    elif pattern[start] == '[':
        return _parse_bracket(pattern, start, end)
    elif pattern[start] == '(':
        alts, i = _parse_alts(pattern, start + 1, end)
        if i < end and pattern[i] == ')':
            i += 1
        return ('group', alts), i
    else:
        return ('char', pattern[start]), start + 1

def _parse_bracket(pattern, start, end):
    i = start + 1
    negated = False
    if i < end and pattern[i] == '^':
        negated = True
        i += 1
    chars = set()
    while i < end and pattern[i] != ']':
        if pattern[i] == '\\' and i + 1 < end:
            chars.add(pattern[i + 1])
            i += 2
        elif (i + 1 < end and pattern[i + 1] == '-' and 
              i + 2 < end and pattern[i + 2] != ']'):
            start_char = pattern[i]
            i += 2
            if pattern[i] == '\\' and i + 1 < end:
                end_char = pattern[i + 1]
                i += 2
            else:
                end_char = pattern[i]
                i += 1
            for c in range(ord(start_char), ord(end_char) + 1):
                chars.add(chr(c))
        else:
            chars.add(pattern[i])
            i += 1
    if i < end:
        i += 1
    return ('bracket', negated, chars), i

def _match(alt, ai, text, ti):
    if ai == len(alt):
        return ti == len(text)

    atom, quantifier = alt[ai]

    if quantifier == '*':
        # Try 0, 1, 2, ... matches
        for i in range(ti, len(text) + 1):
            if _match_atom(atom, text, ti, i - ti):
                if _match(alt, ai + 1, text, i):
                    return True
            else:
                break
        return False
    elif quantifier == '+':
        # Try 1, 2, ... matches
        for i in range(ti + 1, len(text) + 1):
            if _match_atom(atom, text, ti, i - ti):
                if _match(alt, ai + 1, text, i):
                    return True
            else:
                break
        return False
    elif quantifier == '?':
        # Try 0 or 1 match
        if _match_atom(atom, text, ti, 1) and _match(alt, ai + 1, text, ti + 1):
            return True
        return _match(alt, ai + 1, text, ti)
    else:
        # No quantifier, must match exactly one
        if _match_atom(atom, text, ti, 1) and _match(alt, ai + 1, text, ti + 1):
            return True
        return False

def _match_atom(atom, text, start, length):
    if atom[0] == 'char':
        return length == 1 and start < len(text) and text[start] == atom[1]
    elif atom[0] == 'dot':
        return length == 1 and start < len(text)
    elif atom[0] == 'bracket':
        negated, chars = atom[1], atom[2]
        if length != 1 or start >= len(text):
            return False
        c = text[start]
        return (c not in chars) if negated else (c in chars)
    elif atom[0] == 'group':
        group_alts = atom[1]
        if length == 0:
            return False
        for g_alt in group_alts:
            if _match_group_alt(g_alt, 0, text, start, length):
                return True
        return False
    return False

def _match_group_alt(g_alt, ai, text, start, length):
    if ai == len(g_alt):
        return length == 0
    atom, quantifier = g_alt[ai]

    if quantifier == '*':
        for i in range(start, start + length + 1):
            if _match_atom(atom, text, i, min(i - start, length)):
                if _match_group_alt(g_alt, ai + 1, text, i, length):
                    return True
            else:
                break
        return False
    elif quantifier == '+':
        for i in range(start + 1, start + length + 1):
            if _match_atom(atom, text, i, min(i - start, length)):
                if _match_group_alt(g_alt, ai + 1, text, i, length):
                    return True
            else:
                break
        return False
    elif quantifier == '?':
        if _match_atom(atom, text, start, 1) and _match_group_alt(g_alt, ai + 1, text, start + 1, length):
            return True
        return _match_group_alt(g_alt, ai + 1, text, start, length)
    else:
        if _match_atom(atom, text, start, 1) and _match_group_alt(g_alt, ai + 1, text, start + 1, length):
            return True
        return False

def regex_match(pattern: str, text: str) -> bool:
    # Parse the pattern into a list of alternative branches.
    # Each branch is a tuple of nodes. Each node is a tuple: (kind, value, quantifier)
    # kind: 'char', 'dot', 'bracket', 'group'
    # value: char for 'char', set for 'bracket', list of branches for 'group'
    # quantifier: None, '*', '+', '?'

    i = 0
    n = len(pattern)

    def peek():
        return pattern[i] if i < n else None

    def advance():
        nonlocal i
        c = pattern[i]
        i += 1
        return c

    def parse_alt():
        branches = [parse_seq()]
        while peek() == '|':
            advance()
            branches.append(parse_seq())
        return branches

    def parse_seq():
        nodes = []
        while peek() not in (')', '|', None):
            node = parse_atom()
            q = peek()
            if q in ('*', '+', '?'):
                advance()
                node = (node[0], node[1], q)
            nodes.append(node)
        return nodes

    def parse_atom():
        if peek() == '.':
            advance()
            return ('dot', None, None)
        elif peek() == '[':
            return parse_bracket()
        elif peek() == '(':
            advance()
            group_nodes = parse_alt()
            if peek() == ')':
                advance()
            return ('group', group_nodes, None)
        elif peek() == '\\':
            advance()
            c = advance()
            return ('char', c, None)
        else:
            c = advance()
            return ('char', c, None)

    def parse_bracket():
        advance()  # [
        negated = False
        if peek() == '^':
            negated = True
            advance()
        chars = set()
        while peek() != ']':
            if peek() == '\\':
                advance()
                chars.add(advance())
            elif i + 2 < n and pattern[i + 1] == '-' and pattern[i + 2] != ']':
                start = advance()
                advance()  # -
                end = advance()
                for c in range(ord(start), ord(end) + 1):
                    chars.add(chr(c))
            else:
                chars.add(advance())
        if peek() == ']':
            advance()
        return ('bracket', (chars, negated), None)

    branches = parse_alt()
    memo = {}

    def _match(nodes, n_idx, t_idx):
        state = (nodes, t_idx)
        if state in memo:
            return memo[state]

        if n_idx == len(nodes):
            res = (t_idx == len(text))
            memo[state] = res
            return res

        node = nodes[n_idx]
        kind, val, quant = node
        res = False

        # Inline atom matching logic for performance and closure simplicity
        def atom_matches(char):
            if kind == 'char':
                return val == char
            if kind == 'dot':
                return True
            if kind == 'bracket':
                chars, negated = val
                return (char in chars) ^ negated
            if kind == 'group':
                for branch in val:
                    if _match(tuple(branch), 0, t_idx):
                        return True
                return False
            return False

        if quant == '*':
            # Try zero occurrences
            if _match(nodes, n_idx + 1, t_idx):
                res = True
            elif t_idx < len(text) and atom_matches(text[t_idx]):
                # Try one or more occurrences
                if _match(nodes, n_idx, t_idx + 1):
                    res = True
        elif quant == '+':
            # Must match at least one
            if t_idx < len(text) and atom_matches(text[t_idx]):
                if _match(nodes, n_idx, t_idx + 1):
                    res = True
        elif quant == '?':
            # Try zero
            if _match(nodes, n_idx + 1, t_idx):
                res = True
            elif t_idx < len(text) and atom_matches(text[t_idx]):
                # Try one
                if _match(nodes, n_idx + 1, t_idx + 1):
                    res = True
        else:
            # No quantifier
            if t_idx < len(text) and atom_matches(text[t_idx]):
                if _match(nodes, n_idx + 1, t_idx + 1):
                    res = True

        memo[state] = res
        return res

    for branch in branches:
        if _match(tuple(branch), 0, 0):
            return True
    return False

def regex_match(pattern: str, text: str) -> bool:
    # AST Nodes
    class Literal:
        __slots__ = ('char',)
        def __init__(self, char): self.char = char
    class Dot: pass
    class Class:
        __slots__ = ('chars', 'negated')
        def __init__(self, chars, negated=False): 
            self.chars = chars; self.negated = negated
    class Concat:
        __slots__ = ('left', 'right')
        def __init__(self, left, right): self.left = left; self.right = right
    class Alternation:
        __slots__ = ('left', 'right')
        def __init__(self, left, right): self.left = left; self.right = right
    class Quantifier:
        __slots__ = ('atom', 'kind')
        def __init__(self, atom, kind): self.atom = atom; self.kind = kind
    class Empty: pass

    pos = [0]
    pat = pattern
    nfa_states = []
    state_count = [0]

    def new_state(type_='epsilon', value=None):
        idx = state_count[0]
        state_count[0] += 1
        nfa_states.append({'type': type_, 'value': value, 'transitions': [], 'epsilon': []})
        return idx

    def add_transition(from_state, char_set, to_state):
        nfa_states[from_state]['transitions'].append((char_set, to_state))

    def add_epsilon(from_state, to_state):
        nfa_states[from_state]['epsilon'].append(to_state)

    def compile(node):
        if isinstance(node, Literal):
            s_in = new_state('char', node.char)
            s_out = new_state('epsilon')
            add_transition(s_in, node.char, s_out)
            return (s_in, s_out)
        elif isinstance(node, Dot):
            s_in = new_state('dot')
            s_out = new_state('epsilon')
            add_transition(s_in, 'ANY', s_out)
            return (s_in, s_out)
        elif isinstance(node, Class):
            s_in = new_state('class', node)
            s_out = new_state('epsilon')
            add_transition(s_in, node, s_out)
            return (s_in, s_out)
        elif isinstance(node, Concat):
            left_in, left_out = compile(node.left)
            right_in, right_out = compile(node.right)
            add_epsilon(left_out, right_in)
            return (left_in, right_out)
        elif isinstance(node, Alternation):
            s_in = new_state('epsilon')
            s_match = new_state('match')
            left_in, left_out = compile(node.left)
            right_in, right_out = compile(node.right)
            add_epsilon(s_in, left_in)
            add_epsilon(s_in, right_in)
            add_epsilon(left_out, s_match)
            add_epsilon(right_out, s_match)
            return (s_in, s_match)
        elif isinstance(node, Quantifier):
            inner_in, inner_out = compile(node.atom)
            if node.kind == '*':
                s_in = new_state('epsilon')
                s_out = new_state('epsilon')
                add_epsilon(s_in, inner_in)
                add_epsilon(s_in, s_out)
                add_epsilon(inner_out, inner_in)
                add_epsilon(inner_out, s_out)
                return (s_in, s_out)
            elif node.kind == '+':
                s_in = new_state('epsilon')
                s_out = new_state('epsilon')
                add_epsilon(s_in, inner_in)
                add_epsilon(inner_out, inner_in)
                add_epsilon(inner_out, s_out)
                return (s_in, s_out)
            elif node.kind == '?':
                s_in = new_state('epsilon')
                s_out = new_state('epsilon')
                add_epsilon(s_in, inner_in)
                add_epsilon(s_in, s_out)
                add_epsilon(inner_out, s_out)
                return (s_in, s_out)
        elif isinstance(node, Empty):
            s_in = new_state('epsilon')
            s_out = new_state('epsilon')
            add_epsilon(s_in, s_out)
            return (s_in, s_out)
        return None

    # Parser
    def peek():
        if pos[0] < len(pat): return pat[pos[0]]
        return ''

    def advance():
        ch = pat[pos[0]]
        pos[0] += 1
        return ch

    def parse_class():
        advance() # [
        negated = False
        if peek() == '^':
            negated = True
            advance()
        chars = set()
        while peek() != ']' and pos[0] < len(pat):
            ch = advance()
            if peek() == '-' and pos[0] + 1 < len(pat) and pat[pos[0]+1] != ']':
                advance() # -
                end_ch = advance()
                for c in range(ord(ch), ord(end_ch)+1):
                    chars.add(chr(c))
            else:
                chars.add(ch)
        if peek() == ']': advance()
        return Class(chars, negated)

    def parse_atom():
        ch = peek()
        if ch == '(':
            advance()
            node = parse_alternation()
            if peek() == ')': advance()
            return node
        elif ch == '[':
            return parse_class()
        elif ch == '.':
            advance()
            return Dot()
        elif ch == '\\':
            advance()
            return Literal(advance())
        else:
            advance()
            return Literal(ch)

    def parse_quantifier(atom):
        if peek() == '*':
            advance()
            return Quantifier(atom, '*')
        elif peek() == '+':
            advance()
            return Quantifier(atom, '+')
        elif peek() == '?':
            advance()
            return Quantifier(atom, '?')
        return atom

    def parse_concat():
        nodes = []
        while peek() not in ('', ')', '|'):
            nodes.append(parse_quantifier(parse_atom()))
        if len(nodes) == 0:
            return Empty()
        elif len(nodes) == 1:
            return nodes[0]
        else:
            node = nodes[0]
            for n in nodes[1:]:
                node = Concat(node, n)
            return node

    def parse_alternation():
        left = parse_concat()
        while peek() == '|':
            advance()
            right = parse_concat()
            left = Alternation(left, right)
        return left

    root = parse_alternation()
    start_state, end_state = compile(root)

    # Precompute epsilon closures
    epsilon_closure = [set() for _ in range(state_count[0])]
    def compute_closure(start):
        closure = set()
        stack = [start]
        while stack:
            s = stack.pop()
            if s not in closure:
                closure.add(s)
                for ns in nfa_states[s]['epsilon']:
                    stack.append(ns)
        epsilon_closure[start] = closure

    for i in range(state_count[0]):
        compute_closure(i)

    # NFA Simulation
    current_states = epsilon_closure[start_state]

    for ch in text:
        next_states = set()
        for s in current_states:
            state_type = nfa_states[s]['type']
            if state_type == 'char':
                if ch == nfa_states[s]['value']:
                    for ns in nfa_states[s]['transitions'][0][1]:
                        next_states.add(ns)
            elif state_type == 'dot':
                for ns in nfa_states[s]['transitions'][0][1]:
                    next_states.add(ns)
            elif state_type == 'class':
                cls = nfa_states[s]['value']
                match = (ch in cls.chars) ^ cls.negated
                if match:
                    for ns in nfa_states[s]['transitions'][0][1]:
                        next_states.add(ns)
            elif state_type == 'match':
                next_states.add(s)

        current_states = set()
        for ns in next_states:
            current_states.update(epsilon_closure[ns])

    return end_state in current_states

class JSONParser:
    def __init__(self, s: str):
        self.s = s
        self.pos = 0
        self.len_s = len(s)

    def parse(self):
        self.skip_whitespace()
        if self.pos >= self.len_s:
            raise ValueError("Empty input")
        val = self.parse_value()
        self.skip_whitespace()
        if self.pos < self.len_s:
            raise ValueError("Trailing non-whitespace")
        return val

    def skip_whitespace(self):
        while self.pos < self.len_s and self.s[self.pos] in ' \t\n\r':
            self.pos += 1

    def current_char(self):
        if self.pos < self.len_s:
            return self.s[self.pos]
        return None

    def advance(self):
        self.pos += 1

    def expect(self, char):
        if self.current_char() != char:
            raise ValueError(f"Expected '{char}', got '{self.current_char()}'")
        self.advance()

    def parse_value(self):
        self.skip_whitespace()
        c = self.current_char()
        if c == '"':
            return self.parse_string()
        elif c == '{':
            return self.parse_object()
        elif c == '[':
            return self.parse_array()
        elif c == 't':
            return self.parse_true()
        elif c == 'f':
            return self.parse_false()
        elif c == 'n':
            return self.parse_null()
        elif c == '-' or c.isdigit():
            return self.parse_number()
        else:
            raise ValueError(f"Unexpected character: '{c}'")

    def parse_string(self):
        self.expect('"')
        chars = []
        while True:
            if self.pos >= self.len_s:
                raise ValueError("Unterminated string")
            c = self.s[self.pos]
            if c == '"':
                self.advance()
                break
            elif c == '\\':
                self.advance()
                chars.append(self.parse_escape())
            elif ord(c) < 0x20:
                raise ValueError(f"Invalid control character in string: U+{ord(c):04X}")
            else:
                chars.append(c)
                self.advance()
        return ''.join(chars)

    def parse_escape(self):
        if self.pos >= self.len_s:
            raise ValueError("Unterminated escape")
        c = self.s[self.pos]
        self.advance()
        if c == '"':
            return '"'
        elif c == '\\':
            return '\\'
        elif c == '/':
            return '/'
        elif c == 'b':
            return '\b'
        elif c == 'f':
            return '\f'
        elif c == 'n':
            return '\n'
        elif c == 'r':
            return '\r'
        elif c == 't':
            return '\t'
        elif c == 'u':
            return self.parse_unicode_escape()
        else:
            raise ValueError(f"Invalid escape character: '{c}'")

    def parse_unicode_escape(self):
        if self.pos + 4 > self.len_s:
            raise ValueError("Incomplete unicode escape")
        hex_str = self.s[self.pos:self.pos+4]
        self.pos += 4
        try:
            code_point = int(hex_str, 16)
        except ValueError:
            raise ValueError(f"Invalid unicode escape: \\u{hex_str}")

        if 0xD800 <= code_point <= 0xDBFF:
            if self.pos + 6 <= self.len_s and self.s[self.pos] == '\\' and self.s[self.pos+1] == 'u':
                low_hex = self.s[self.pos+2:self.pos+6]
                self.pos += 6
                try:
                    low_code_point = int(low_hex, 16)
                except ValueError:
                    raise ValueError(f"Invalid unicode escape in pair: \\u{low_hex}")
                if 0xDC00 <= low_code_point <= 0xDFFF:
                    combined = 0x10000 + (code_point - 0xD800) * 0x400 + (low_code_point - 0xDC00)
                    return chr(combined)
                else:
                    return chr(code_point)
            else:
                return chr(code_point)
        elif 0xDC00 <= code_point <= 0xDFFF:
            return chr(code_point)
        else:
            return chr(code_point)

    def parse_number(self):
        start = self.pos
        if self.current_char() == '-':
            self.advance()

        if self.pos >= self.len_s:
            raise ValueError("Incomplete number")

        c = self.s[self.pos]
        if c == '0':
            self.advance()
            if self.pos < self.len_s and self.s[self.pos].isdigit():
                raise ValueError("Leading zeros not allowed")
        elif c.isdigit():
            self.advance()
            while self.pos < self.len_s and self.s[self.pos].isdigit():
                self.advance()
        else:
            raise ValueError("Invalid number start")

        is_float = False
        if self.pos < self.len_s and self.s[self.pos] == '.':
            is_float = True
            self.advance()
            if self.pos >= self.len_s or not self.s[self.pos].isdigit():
                raise ValueError("Invalid number: expected digit after '.'")
            while self.pos < self.len_s and self.s[self.pos].isdigit():
                self.advance()

        if self.pos < self.len_s and self.s[self.pos] in ('e', 'E'):
            is_float = True
            self.advance()
            if self.pos < self.len_s and self.s[self.pos] in ('+', '-'):
                self.advance()
            if self.pos >= self.len_s or not self.s[self.pos].isdigit():
                raise ValueError("Invalid number: expected digit in exponent")
            while self.pos < self.len_s and self.s[self.pos].isdigit():
                self.advance()

        num_str = self.s[start:self.pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_object(self):
        self.expect('{')
        obj = {}
        self.skip_whitespace()
        if self.current_char() == '}':
            self.advance()
            return obj

        while True:
            self.skip_whitespace()
            if self.current_char() != '"':
                raise ValueError("Expected string key in object")
            key = self.parse_string()
            self.skip_whitespace()
            self.expect(':')
            self.skip_whitespace()
            value = self.parse_value()
            obj[key] = value
            self.skip_whitespace()
            c = self.current_char()
            if c == ',':
                self.advance()
                self.skip_whitespace()
                if self.current_char() == '}':
                    raise ValueError("Trailing comma in object")
                continue
            elif c == '}':
                self.advance()
                return obj
            else:
                raise ValueError(f"Expected ',' or '}}' in object, got '{c}'")

    def parse_array(self):
        self.expect('[')
        arr = []
        self.skip_whitespace()
        if self.current_char() == ']':
            self.advance()
            return arr

        while True:
            self.skip_whitespace()
            value = self.parse_value()
            arr.append(value)
            self.skip_whitespace()
            c = self.current_char()
            if c == ',':
                self.advance()
                self.skip_whitespace()
                if self.current_char() == ']':
                    raise ValueError("Trailing comma in array")
                continue
            elif c == ']':
                self.advance()
                return arr
            else:
                raise ValueError(f"Expected ',' or ']' in array, got '{c}'")

    def parse_true(self):
        if self.s[self.pos:self.pos+4] == 'true':
            self.pos += 4
            return True
        raise ValueError("Invalid literal 'true'")

    def parse_false(self):
        if self.s[self.pos:self.pos+5] == 'false':
            self.pos += 5
            return False
        raise ValueError("Invalid literal 'false'")

    def parse_null(self):
        if self.s[self.pos:self.pos+4] == 'null':
            self.pos += 4
            return None
        raise ValueError("Invalid literal 'null'")

def json_parse(s: str):
    parser = JSONParser(s)
    return parser.parse()

import math

def json_parse(s: str):
    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def peek(self):
            return self.s[self.pos] if self.pos < self.n else None

        def advance(self):
            ch = self.s[self.pos]
            self.pos += 1
            return ch

        def skip_ws(self):
            while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
                self.pos += 1

        def parse(self):
            self.skip_ws()
            if self.pos >= self.n:
                raise ValueError("Empty input")
            val = self.parse_value()
            self.skip_ws()
            if self.pos < self.n:
                raise ValueError("Trailing non-whitespace")
            return val

        def parse_value(self):
            self.skip_ws()
            ch = self.peek()
            if ch == '{': return self.parse_object()
            if ch == '[': return self.parse_array()
            if ch == '"': return self.parse_string()
            if ch == 't': return self.parse_true()
            if ch == 'f': return self.parse_false()
            if ch == 'n': return self.parse_null()
            if ch == '-' or (ch and ch.isdigit()): return self.parse_number()
            raise ValueError(f"Unexpected character: {ch!r}")

        def parse_object(self):
            self.advance()
            self.skip_ws()
            d = {}
            if self.peek() == '}':
                self.advance()
                return d
            while True:
                self.skip_ws()
                if self.peek() != '"':
                    raise ValueError("Expected object key")
                key = self.parse_string()
                self.skip_ws()
                if self.advance() != ':':
                    raise ValueError("Expected ':'")
                self.skip_ws()
                val = self.parse_value()
                d[key] = val
                self.skip_ws()
                ch = self.peek()
                if ch == '}':
                    self.advance()
                    return d
                if ch == ',':
                    self.advance()
                    self.skip_ws()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma")
                else:
                    raise ValueError("Expected ',' or '}'")

        def parse_array(self):
            self.advance()
            self.skip_ws()
            lst = []
            if self.peek() == ']':
                self.advance()
                return lst
            while True:
                self.skip_ws()
                val = self.parse_value()
                lst.append(val)
                self.skip_ws()
                ch = self.peek()
                if ch == ']':
                    self.advance()
                    return lst
                if ch == ',':
                    self.advance()
                    self.skip_ws()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma")
                else:
                    raise ValueError("Expected ',' or ']'")

        def parse_string(self):
            self.advance()
            chars = []
            while self.pos < self.n:
                ch = self.advance()
                if ch == '"':
                    return ''.join(chars)
                if ch == '\\':
                    esc = self.advance()
                    if esc == '"': chars.append('"')
                    elif esc == '\\': chars.append('\\')
                    elif esc == '/': chars.append('/')
                    elif esc == 'b': chars.append('\b')
                    elif esc == 'f': chars.append('\f')
                    elif esc == 'n': chars.append('\n')
                    elif esc == 'r': chars.append('\r')
                    elif esc == 't': chars.append('\t')
                    elif esc == 'u':
                        if self.pos + 4 > self.n:
                            raise ValueError("Invalid unicode escape")
                        h = self.s[self.pos:self.pos+4]
                        if not all(c in '0123456789abcdefABCDEF' for c in h):
                            raise ValueError("Invalid unicode escape")
                        cp = int(h, 16)
                        self.pos += 4
                        if 0xD800 <= cp <= 0xDBFF:
                            if self.pos + 6 <= self.n and self.s[self.pos:self.pos+2] == '\\u':
                                h2 = self.s[self.pos+2:self.pos+6]
                                if all(c in '0123456789abcdefABCDEF' for c in h2):
                                    low = int(h2, 16)
                                    if 0xDC00 <= low <= 0xDFFF:
                                        self.pos += 6
                                        chars.append(chr(0x10000 + (cp - 0xD800) * 0x400 + (low - 0xDC00)))
                                        continue
                            chars.append(chr(cp))
                        else:
                            chars.append(chr(cp))
                    else:
                        raise ValueError(f"Invalid escape: {esc!r}")
                elif ord(ch) < 0x20:
                    raise ValueError("Unescaped control character")
                else:
                    chars.append(ch)
            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            if self.peek() == '-':
                self.advance()
            if self.pos >= self.n:
                raise ValueError("Unexpected end of number")
            if self.peek() == '0':
                self.advance()
                if self.pos < self.n and self.s[self.pos].isdigit():
                    raise ValueError("Leading zeros not allowed")
            elif self.peek() in '123456789':
                self.advance()
                while self.pos < self.n and self.s[self.pos].isdigit():
                    self.advance()
            else:
                raise ValueError("Invalid number")

            is_float = False
            if self.pos < self.n and self.s[self.pos] == '.':
                is_float = True
                self.advance()
                if self.pos >= self.n or not self.s[self.pos].isdigit():
                    raise ValueError("Invalid number")
                while self.pos < self.n and self.s[self.pos].isdigit():
                    self.advance()

            if self.pos < self.n and self.s[self.pos] in 'eE':
                is_float = True
                self.advance()
                if self.pos < self.n and self.s[self.pos] in '+-':
                    self.advance()
                if self.pos >= self.n or not self.s[self.pos].isdigit():
                    raise ValueError("Invalid number")
                while self.pos < self.n and self.s[self.pos].isdigit():
                    self.advance()

            num_str = self.s[start:self.pos]
            if is_float:
                v = float(num_str)
                if math.isinf(v) or math.isnan(v):
                    raise ValueError("NaN/Infinity not allowed")
                return v
            return int(num_str)

        def parse_true(self):
            if self.s[self.pos:self.pos+4] == 'true':
                self.pos += 4
                return True
            raise ValueError("Invalid literal")

        def parse_false(self):
            if self.s[self.pos:self.pos+5] == 'false':
                self.pos += 5
                return False
            raise ValueError("Invalid literal")

        def parse_null(self):
            if self.s[self.pos:self.pos+4] == 'null':
                self.pos += 4
                return None
            raise ValueError("Invalid literal")

    return Parser(s).parse()

class JSONParser:
    def __init__(self, s: str):
        self.s = s
        self.pos = 0
        self.len = len(s)

    def parse(self):
        self.skip_whitespace()
        if self.pos >= self.len:
            raise ValueError("Empty input")
        val = self.parse_value()
        self.skip_whitespace()
        if self.pos < self.len:
            raise ValueError("Trailing non-whitespace")
        return val

    def skip_whitespace(self):
        while self.pos < self.len and self.s[self.pos] in ' \t\n\r':
            self.pos += 1

    def parse_value(self):
        self.skip_whitespace()
        if self.pos >= self.len:
            raise ValueError("Unexpected end of input")
        c = self.s[self.pos]
        if c == '{':
            return self.parse_object()
        elif c == '[':
            return self.parse_array()
        elif c == '"':
            return self.parse_string()
        elif c == 't':
            return self.parse_true()
        elif c == 'f':
            return self.parse_false()
        elif c == 'n':
            return self.parse_null()
        elif c == '-' or c.isdigit():
            return self.parse_number()
        else:
            raise ValueError(f"Unexpected character: {c}")

    def parse_object(self):
        self.pos += 1  # skip '{'
        self.skip_whitespace()
        result = {}
        if self.pos < self.len and self.s[self.pos] == '}':
            self.pos += 1
            return result

        while True:
            # Parse key
            if self.pos >= self.len or self.s[self.pos] != '"':
                raise ValueError("Expected string key")
            key = self.parse_string()

            self.skip_whitespace()
            if self.pos >= self.len or self.s[self.pos] != ':':
                raise ValueError("Expected ':'")
            self.pos += 1

            self.skip_whitespace()
            value = self.parse_value()
            result[key] = value

            self.skip_whitespace()
            if self.pos >= self.len:
                raise ValueError("Unterminated object")

            c = self.s[self.pos]
            if c == ',':
                self.pos += 1
                self.skip_whitespace()
                # Check for trailing comma
                if self.pos < self.len and self.s[self.pos] == '}':
                    raise ValueError("Trailing comma in object")
            elif c == '}':
                self.pos += 1
                return result
            else:
                raise ValueError("Expected ',' or '}' in object")

    def parse_array(self):
        self.pos += 1  # skip '['
        self.skip_whitespace()
        result = []
        if self.pos < self.len and self.s[self.pos] == ']':
            self.pos += 1
            return result

        while True:
            value = self.parse_value()
            result.append(value)

            self.skip_whitespace()
            if self.pos >= self.len:
                raise ValueError("Unterminated array")

            c = self.s[self.pos]
            if c == ',':
                self.pos += 1
                self.skip_whitespace()
                # Check for trailing comma
                if self.pos < self.len and self.s[self.pos] == ']':
                    raise ValueError("Trailing comma in array")
            elif c == ']':
                self.pos += 1
                return result
            else:
                raise ValueError("Expected ',' or ']' in array")

    def parse_string(self):
        if self.pos >= self.len or self.s[self.pos] != '"':
            raise ValueError("Expected '\"'")
        self.pos += 1
        chars = []
        while self.pos < self.len:
            c = self.s[self.pos]
            if c == '"':
                self.pos += 1
                return "".join(chars)
            if c == '\\':
                self.pos += 1
                if self.pos >= self.len:
                    raise ValueError("Unexpected end of string")
                esc = self.s[self.pos]
                self.pos += 1
                if esc == '"':
