                            self.s[self.pos] == '\\' and 
                            self.s[self.pos+1] == 'u'):
                            if self.pos + 5 < self.len:
                                hex_str2 = self.s[self.pos+2 : self.pos+6]
                                if all(h in '0123456789abcdefABCDEF' for h in hex_str2):
                                    cp2 = int(hex_str2, 16)
                                    if 0xDC00 <= cp2 <= 0xDFFF: # Low surrogate
                                        combined = 0x10000 + (cp - 0xD800) * 0x400 + (cp2 - 0xDC00)
                                        chars.append(chr(combined))
                                        self.pos += 6 # Skip \uXXXX
                                        continue
                    # Unpaired surrogate or non-surrogate
                    chars.append(chr(cp))
                else:
                    raise ValueError(f"Invalid escape character: {esc}")
            else:
                if ord(c) < 0x20:
                    raise ValueError("Raw control character not allowed")
                chars.append(c)
                self.pos += 1
        raise ValueError("Unterminated string")

    def parse_number(self):
        start = self.pos
        has_fraction = False
        has_exponent = False

        # Optional sign
        if self.pos < self.len and self.s[self.pos] == '-':
            self.pos += 1

        if self.pos >= self.len or self.s[self.pos] not in '0123456789':
            raise ValueError("Invalid number")

        # Integer part
        if self.s[self.pos] == '0':
            self.pos += 1
            # Check for leading zeros (e.g., 01)
            if self.pos < self.len and self.s[self.pos] in '0123456789':
                raise ValueError("Leading zeros not allowed")
        else:
            # 1-9 followed by digits
            while self.pos < self.len and self.s[self.pos] in '0123456789':
                self.pos += 1

        # Fractional part
        if self.pos < self.len and self.s[self.pos] == '.':
            has_fraction = True
            self.pos += 1
            if self.pos >= self.len or self.s[self.pos] not in '0123456789':
                raise ValueError("Invalid number: fraction requires digits")
            while self.pos < self.len and self.s[self.pos] in '0123456789':
                self.pos += 1

        # Exponent part
        if self.pos < self.len and self.s[self.pos] in 'eE':
            has_exponent = True
            self.pos += 1
            if self.pos < self.len and self.s[self.pos] in '+-':
                self.pos += 1
            if self.pos >= self.len or self.s[self.pos] not in '0123456789':
                raise ValueError("Invalid number: exponent requires digits")
            while self.pos < self.len and self.s[self.pos] in '0123456789':
                self.pos += 1

        num_str = self.s[start:self.pos]
        if has_fraction or has_exponent:
            # Float
            # Check for NaN/Infinity (though regex/logic prevents it, just in case)
            # Python's float() handles standard formats.
            try:
                val = float(num_str)
                if val != val or val == float('inf') or val == float('-inf'):
                    raise ValueError("NaN/Infinity not allowed")
                return val
            except ValueError:
                raise ValueError("Invalid number format")
        else:
            # Int
            try:
                return int(num_str)
            except ValueError:
                raise ValueError("Invalid number format")

    def parse_true(self):
        if self.s[self.pos:self.pos+4] == 'true':
            self.pos += 4
            return True
        raise ValueError("Invalid literal")

    def parse_false(self):
        if self.s[self.pos:self.pos+5] == 'false':
            self.pos += 5
            return False
        raise ValueError("Invalid literal")

    def parse_null(self):
        if self.s[self.pos:self.pos+4] == 'null':
            self.pos += 4
            return None
        raise ValueError("Invalid literal")

def json_parse(s: str):
    parser = JSONParser(s)
    return parser.parse()

def json_parse(s: str):
    class Parser:
        DIGITS = frozenset('0123456789')
        HEX = frozenset('0123456789abcdefABCDEF')

        def __init__(self, text: str):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def error(self, msg="Invalid JSON"):
            raise ValueError(msg)

        def peek(self):
            if self.pos < self.length:
                return self.text[self.pos]
            return None

        def advance(self):
            ch = self.text[self.pos]
            self.pos += 1
            return ch

        def skip_whitespace(self):
            while self.pos < self.length and self.text[self.pos] in ' \t\n\r':
                self.pos += 1

        def parse(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                self.error("Empty input")
            val = self.parse_value()
            self.skip_whitespace()
            if self.pos < self.length:
                self.error("Trailing non-whitespace")
            return val

        def parse_value(self):
            ch = self.peek()
            if ch == '"':
                return self.parse_string()
            elif ch == '{':
                return self.parse_object()
            elif ch == '[':
                return self.parse_array()
            elif ch == 't':
                return self.parse_true()
            elif ch == 'f':
                return self.parse_false()
            elif ch == 'n':
                return self.parse_null()
            elif ch == '-' or ch in self.DIGITS:
                return self.parse_number()
            else:
                self.error(f"Unexpected character: {ch!r}")

        def parse_string(self):
            self.advance()  # skip opening "
            chars = []
            while True:
                if self.pos >= self.length:
                    self.error("Unterminated string")
                ch = self.advance()
                if ch == '"':
                    return "".join(chars)
                elif ch == '\\':
                    if self.pos >= self.length:
                        self.error("Unterminated escape")
                    esc = self.advance()
                    if esc == '"':
                        chars.append('"')
                    elif esc == '\\':
                        chars.append('\\')
                    elif esc == '/':
                        chars.append('/')
                    elif esc == 'b':
                        chars.append('\b')
                    elif esc == 'f':
                        chars.append('\f')
                    elif esc == 'n':
                        chars.append('\n')
                    elif esc == 'r':
                        chars.append('\r')
                    elif esc == 't':
                        chars.append('\t')
                    elif esc == 'u':
                        if self.pos + 4 > self.length:
                            self.error("Invalid unicode escape")
                        hex_str = self.text[self.pos:self.pos + 4]
                        if not all(c in self.HEX for c in hex_str):
                            self.error("Invalid hex in unicode escape")
                        code_point = int(hex_str, 16)
                        self.pos += 4

                        if 0xD800 <= code_point <= 0xDBFF:
                            # High surrogate
                            if self.pos + 6 <= self.length and self.text[self.pos:self.pos + 2] == '\\u':
                                hex_str2 = self.text[self.pos + 2:self.pos + 6]
                                if all(c in self.HEX for c in hex_str2):
                                    self.pos += 6
                                    low = int(hex_str2, 16)
                                    if 0xDC00 <= low <= 0xDFFF:
                                        code_point = 0x10000 + (code_point - 0xD800) * 0x400 + (low - 0xDC00)
                                else:
                                    self.error("Invalid hex in unicode escape")
                            # else: lone high surrogate, code_point stays as is
                        elif 0xDC00 <= code_point <= 0xDFFF:
                            # Lone low surrogate, stays as is
                            pass
                        # else: normal character

                        chars.append(chr(code_point))
                    else:
                        self.error(f"Invalid escape character: {esc!r}")
                else:
                    if ord(ch) < 0x20:
                        self.error("Raw control character in string")
                    chars.append(ch)

        def parse_number(self):
            start = self.pos
            if self.peek() == '-':
                self.advance()
            if self.pos >= self.length:
                self.error("Trailing minus sign")
            ch = self.peek()
            if ch == '0':
                self.advance()
                if self.pos < self.length and self.text[self.pos] in self.DIGITS:
                    self.error("Leading zeros not allowed")
            elif ch in self.DIGITS:
                while self.pos < self.length and self.text[self.pos] in self.DIGITS:
                    self.advance()
            else:
                self.error("Invalid number")

            is_float = False
            if self.pos < self.length and self.text[self.pos] == '.':
                is_float = True
                self.advance()
                if self.pos >= self.length or self.text[self.pos] not in self.DIGITS:
                    self.error("Invalid number: expected digit after dot")
                while self.pos < self.length and self.text[self.pos] in self.DIGITS:
                    self.advance()

            if self.pos < self.length and self.text[self.pos] in 'eE':
                is_float = True
                self.advance()
                if self.pos < self.length and self.text[self.pos] in '+-':
                    self.advance()
                if self.pos >= self.length or self.text[self.pos] not in self.DIGITS:
                    self.error("Invalid number: expected digit after exponent")
                while self.pos < self.length and self.text[self.pos] in self.DIGITS:
                    self.advance()

            num_str = self.text[start:self.pos]
            if is_float:
                return float(num_str)
            else:
                return int(num_str)

        def parse_object(self):
            self.advance()  # skip {
            self.skip_whitespace()
            result = {}
            if self.peek() == '}':
                self.advance()
                return result
            while True:
                if self.peek() != '"':
                    self.error("Object key must be a string")
                key = self.parse_string()
                self.skip_whitespace()
                if self.peek() != ':':
                    self.error("Expected ':' after object key")
                self.advance()
                self.skip_whitespace()
                val = self.parse_value()
                result[key] = val
                self.skip_whitespace()
                ch = self.peek()
                if ch == ',':
                    self.advance()
                    self.skip_whitespace()
                elif ch == '}':
                    self.advance()
                    return result
                else:
                    self.error("Expected ',' or '}' in object")

        def parse_array(self):
            self.advance()  # skip [
            self.skip_whitespace()
            result = []
            if self.peek() == ']':
                self.advance()
                return result
            while True:
                val = self.parse_value()
                result.append(val)
                self.skip_whitespace()
                ch = self.peek()
                if ch == ',':
                    self.advance()
                    self.skip_whitespace()
                elif ch == ']':
                    self.advance()
                    return result
                else:
                    self.error("Expected ',' or ']' in array")

        def parse_true(self):
            if self.pos + 4 <= self.length and self.text[self.pos:self.pos + 4] == 'true':
                self.pos += 4
                return True
            self.error("Invalid literal")

        def parse_false(self):
            if self.pos + 5 <= self.length and self.text[self.pos:self.pos + 5] == 'false':
                self.pos += 5
                return False
            self.error("Invalid literal")

        def parse_null(self):
            if self.pos + 4 <= self.length and self.text[self.pos:self.pos + 4] == 'null':
                self.pos += 4
                return None
            self.error("Invalid literal")

    return Parser(s).parse()

def json_parse(s: str):
    if not s:
        raise ValueError("Empty input")
    pos = [0]
    n = len(s)

    def skip_ws():
        while pos[0] < n and s[pos[0]] in ' \t\n\r':
            pos[0] += 1

    def parse_value():
        skip_ws()
        if pos[0] >= n:
            raise ValueError("Unexpected end of input")
        c = s[pos[0]]
        if c == '"':
            return parse_string()
        elif c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == 't':
            return parse_true()
        elif c == 'f':
            return parse_false()
        elif c == 'n':
            return parse_null()
        elif c == '-' or '0' <= c <= '9':
            return parse_number()
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    def parse_string():
        if s[pos[0]] != '"':
            raise ValueError("Expected '\"'")
        pos[0] += 1
        chars = []
        while pos[0] < n:
            c = s[pos[0]]
            if c == '"':
                pos[0] += 1
                return ''.join(chars)
            if c == '\\':
                pos[0] += 1
                if pos[0] >= n:
                    raise ValueError("Unexpected end in string escape")
                esc = s[pos[0]]
                if esc == '"': chars.append('"')
                elif esc == '\\': chars.append('\\')
                elif esc == '/': chars.append('/')
                elif esc == 'b': chars.append('\b')
                elif esc == 'f': chars.append('\f')
                elif esc == 'n': chars.append('\n')
                elif esc == 'r': chars.append('\r')
                elif esc == 't': chars.append('\t')
                elif esc == 'u':
                    pos[0] += 1
                    if pos[0] + 4 > n:
                        raise ValueError("Incomplete unicode escape")
                    hex_str = s[pos[0:pos[0]+4]]
                    if not all(ch in '0123456789abcdefABCDEF' for ch in hex_str):
                        raise ValueError("Invalid unicode escape hex")
                    code_point = int(hex_str, 16)
                    pos[0] += 4
                    if 0xD800 <= code_point <= 0xDBFF:
                        if pos[0] + 2 > n or s[pos[0]] != '\\' or s[pos[0]+1] != 'u':
                            raise ValueError("High surrogate without low surrogate")
                        pos[0] += 2
                        hex_str2 = s[pos[0:pos[0]+4]]
                        if not all(ch in '0123456789abcdefABCDEF' for ch in hex_str2):
                            raise ValueError("Invalid low surrogate hex")
                        low = int(hex_str2, 16)
                        pos[0] += 4
                        if not (0xDC00 <= low <= 0xDFFF):
                            raise ValueError("Low surrogate expected")
                        code_point = 0x10000 + (code_point - 0xD800) * 0x400 + (low - 0xDC00)
                        chars.append(chr(code_point))
                    elif 0xDC00 <= code_point <= 0xDFFF:
                        chars.append(chr(code_point))
                    else:
                        chars.append(chr(code_point))
                else:
                    raise ValueError(f"Invalid escape: \\{esc}")
            else:
                if ord(c) < 0x20:
                    raise ValueError(f"Raw control character in string: {ord(c)}")
                chars.append(c)
            pos[0] += 1
        raise ValueError("Unterminated string")

    def parse_number():
        start = pos[0]
        if pos[0] < n and s[pos[0]] == '-':
            pos[0] += 1
        if pos[0] >= n or not ('0' <= s[pos[0]] <= '9'):
            raise ValueError("Expected digit after '-'")
        if s[pos[0]] == '0':
            pos[0] += 1
            if pos[0] < n and ('0' <= s[pos[0]] <= '9'):
                raise ValueError("Leading zero in number")
        else:
            while pos[0] < n and ('0' <= s[pos[0]] <= '9'):
                pos[0] += 1
        is_float = False
        if pos[0] < n and s[pos[0]] == '.':
            is_float = True
            pos[0] += 1
            if pos[0] >= n or not ('0' <= s[pos[0]] <= '9'):
                raise ValueError("Expected digit after '.'")
            while pos[0] < n and ('0' <= s[pos[0]] <= '9'):
                pos[0] += 1
        if pos[0] < n and s[pos[0]] in 'eE':
            is_float = True
            pos[0] += 1
            if pos[0] < n and s[pos[0]] in '+-':
                pos[0] += 1
            if pos[0] >= n or not ('0' <= s[pos[0]] <= '9'):
                raise ValueError("Expected digit in exponent")
            while pos[0] < n and ('0' <= s[pos[0]] <= '9'):
                pos[0] += 1
        num_str = s[start:pos[0]]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_object():
        if s[pos[0]] != '{':
            raise ValueError("Expected '{'")
        pos[0] += 1
        obj = {}
        skip_ws()
        if pos[0] < n and s[pos[0]] == '}':
            pos[0] += 1
            return obj
        while True:
            skip_ws()
            if pos[0] >= n:
                raise ValueError("Unterminated object")
            if s[pos[0]] != '"':
                raise ValueError("Expected string key")
            key = parse_string()
            skip_ws()
            if pos[0] >= n or s[pos[0]] != ':':
                raise ValueError("Expected ':'")
            pos[0] += 1
            val = parse_value()
            obj[key] = val
            skip_ws()
            if pos[0] >= n:
                raise ValueError("Unterminated object")
            if s[pos[0]] == '}':
                pos[0] += 1
                return obj
            elif s[pos[0]] == ',':
                pos[0] += 1
            else:
                raise ValueError(f"Expected ',' or '}}', got {s[pos[0]]!r}")

    def parse_array():
        if s[pos[0]] != '[':
            raise ValueError("Expected '['")
        pos[0] += 1
        arr = []
        skip_ws()
        if pos[0] < n and s[pos[0]] == ']':
            pos[0] += 1
            return arr
        while True:
            val = parse_value()
            arr.append(val)
            skip_ws()
            if pos[0] >= n:
                raise ValueError("Unterminated array")
            if s[pos[0]] == ']':
                pos[0] += 1
                return arr
            elif s[pos[0]] == ',':
                pos[0] += 1
            else:
                raise ValueError(f"Expected ',' or ']', got {s[pos[0]]!r}")

    def parse_true():
        if s[pos[0:pos[0]+4]] == 'true':
            pos[0] += 4
            return True
        raise ValueError("Invalid literal")

    def parse_false():
        if s[pos[0:pos[0]+5]] == 'false':
            pos[0] += 5
            return False
        raise ValueError("Invalid literal")

    def parse_null():
        if s[pos[0:pos[0]+4]] == 'null':
            pos[0] += 4
            return None
        raise ValueError("Invalid literal")

    result = parse_value()
    skip_ws()
    if pos[0] < n:
        raise ValueError("Trailing non-whitespace")
    return result

def json_parse(s: str):
    pos = 0
    length = len(s)

    def error(msg):
        raise ValueError(msg)

    def skip_ws():
        nonlocal pos
        while pos < length and s[pos] in ' \t\n\r':
            pos += 1

    def advance():
        nonlocal pos
        pos += 1
        return s[pos-1]

    def parse_string():
        nonlocal pos
        if advance() != '"':
            error("Expected '\"'")
        chars = []
        while True:
            if pos >= length:
                error("Unterminated string")
            c = advance()
            if c == '"':
                return ''.join(chars)
            elif c == '\\':
                if pos >= length:
                    error("Unterminated escape")
                esc = advance()
                if esc == '"': chars.append('"')
                elif esc == '\\': chars.append('\\')
                elif esc == '/': chars.append('/')
                elif esc == 'b': chars.append('\b')
                elif esc == 'f': chars.append('\f')
                elif esc == 'n': chars.append('\n')
                elif esc == 'r': chars.append('\r')
                elif esc == 't': chars.append('\t')
                elif esc == 'u':
                    if pos + 4 > length:
                        error("Incomplete unicode escape")
                    hex_str = s[pos:pos+4]
                    if not all(h in '0123456789abcdefABCDEF' for h in hex_str):
                        error("Invalid hex digits in unicode escape")
                    cp = int(hex_str, 16)
                    pos += 4

                    if 0xD800 <= cp <= 0xDBFF:
                        if pos + 4 <= length and s[pos:pos+2] == '\\u':
                            hex_str2 = s[pos+2:pos+6]
                            if all(h in '0123456789abcdefABCDEF' for h in hex_str2):
                                cp2 = int(hex_str2, 16)
                                if 0xDC00 <= cp2 <= 0xDFFF:
                                    cp = 0x10000 + (cp - 0xD800) * 0x400 + (cp2 - 0xDC00)
                                    pos += 6
                        chars.append(chr(cp))
                    else:
                        chars.append(chr(cp))
                else:
                    error(f"Invalid escape: {esc!r}")
            else:
                if ord(c) < 0x20:
                    error(f"Invalid control character in string: {ord(c)}")
                chars.append(c)

    def parse_number():
        nonlocal pos
        start = pos
        if pos < length and s[pos] == '-':
            pos += 1
        if pos >= length:
            error("Invalid number")
        if s[pos] == '0':
            pos += 1
            if pos < length and s[pos] in '0123456789':
                error("Leading zeros not allowed")
        elif s[pos] in '123456789':
            pos += 1
            while pos < length and s[pos] in '0123456789':
                pos += 1
        else:
            error("Invalid number")

        is_float = False
        if pos < length and s[pos] == '.':
            is_float = True
            pos += 1
            if pos >= length or s[pos] not in '0123456789':
                error("Invalid number: expected digit after '.'")
            while pos < length and s[pos] in '0123456789':
                pos += 1

        if pos < length and s[pos] in 'eE':
            is_float = True
            pos += 1
            if pos < length and s[pos] in '+-':
                pos += 1
            if pos >= length or s[pos] not in '0123456789':
                error("Invalid number: expected digit in exponent")
            while pos < length and s[pos] in '0123456789':
                pos += 1

        num_str = s[start:pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_value():
        nonlocal pos
        skip_ws()
        if pos >= length:
            error("Unexpected end of input")
        c = s[pos]
        if c == '"':
            return parse_string()
        elif c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == 't':
            return parse_true()
        elif c == 'f':
            return parse_false()
        elif c == 'n':
            return parse_null()
        elif c == '-' or c.isdigit():
            return parse_number()
        else:
            error(f"Unexpected character: {c!r}")

    def parse_true():
        nonlocal pos
        if s[pos:pos+4] == 'true':
            end = pos + 4
            if end < length and s[end].isalnum():
                error("Invalid literal")
            pos = end
            return True
        error("Invalid literal")

    def parse_false():
        nonlocal pos
        if s[pos:pos+5] == 'false':
            end = pos + 5
            if end < length and s[end].isalnum():
                error("Invalid literal")
            pos = end
            return False
        error("Invalid literal")

    def parse_null():
        nonlocal pos
        if s[pos:pos+4] == 'null':
            end = pos + 4
            if end < length and s[end].isalnum():
                error("Invalid literal")
            pos = end
            return None
        error("Invalid literal")

    def parse_object():
        nonlocal pos
        if advance() != '{':
            error("Expected '{'")
        skip_ws()
        if pos < length and s[pos] == '}':
            pos += 1
            return {}
        obj = {}
        while True:
            skip_ws()
            if pos >= length:
                error("Unterminated object")
            if s[pos] != '"':
                error("Expected string key in object")
            key = parse_string()
            skip_ws()
            if pos >= length or s[pos] != ':':
                error("Expected ':'")
            pos += 1
            skip_ws()
            val = parse_value()
            obj[key] = val
            skip_ws()
            if pos >= length:
                error("Unterminated object")
            if s[pos] == '}':
                pos += 1
                return obj
            elif s[pos] == ',':
                pos += 1
                skip_ws()
                if pos < length and s[pos] == '}':
                    error("Trailing comma in object")
            else:
                error(f"Expected ',' or '}}' in object, got {s[pos]!r}")

    def parse_array():
        nonlocal pos
        if advance() != '[':
            error("Expected '['")
        skip_ws()
        if pos < length and s[pos] == ']':
            pos += 1
            return []
        arr = []
        while True:
            val = parse_value()
            arr.append(val)
            skip_ws()
            if pos >= length:
                error("Unterminated array")
            if s[pos] == ']':
                pos += 1
                return arr
            elif s[pos] == ',':
                pos += 1
                skip_ws()
                if pos < length and s[pos] == ']':
                    error("Trailing comma in array")
            else:
                error(f"Expected ',' or ']' in array, got {s[pos]!r}")

    result = parse_value()
    skip_ws()
    if pos < length:
        error("Trailing non-whitespace")
    return result

class _JSONParser:
    def __init__(self, s: str):
        self.text = s
        self.pos = 0
        self.length = len(s)

    def skip_whitespace(self):
        while self.pos < self.length and self.text[self.pos] in ' \t\n\r':
            self.pos += 1

    def expect(self, c: str):
        if self.pos >= self.length or self.text[self.pos] != c:
            raise ValueError(f"Expected {c!r} at position {self.pos}")
        self.pos += 1

    def parse_value(self):
        self.skip_whitespace()
        if self.pos >= self.length:
            raise ValueError("Empty input")
        c = self.text[self.pos]
        if c == '{':
            return self.parse_object()
        if c == '[':
            return self.parse_array()
        if c == '"':
            return self.parse_string()
        if c == 't':
            return self.parse_true()
        if c == 'f':
            return self.parse_false()
        if c == 'n':
            return self.parse_null()
        if c == '-' or c.isdigit():
