    def parse_false(self):
        self.expect('f')
        self.expect('a')
        self.expect('l')
        self.expect('s')
        self.expect('e')
        return False

    def parse_null(self):
        self.expect('n')
        self.expect('u')
        self.expect('l')
        self.expect('l')
        return None


