                raise ValueError("Expected ',' or ']' in array")

    def parse():
        skip_ws()
        if pos[0] >= length:
            raise ValueError("Empty input")
        return parse_value()

    def expect_eof():
        skip_ws()
        if pos[0] < length:
            raise ValueError("Trailing non-whitespace")

    result = parse()
    expect_eof()
    return result

def json_parse(s: str):
    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def err(self, msg="Invalid JSON"):
            raise ValueError(msg)

        def ws(self):
            while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
                self.pos += 1

        def expect(self, c):
            if self.pos >= self.n or self.s[self.pos] != c:
                self.err(f"Expected '{c}'")
            self.pos += 1

        def val(self):
            self.ws()
            if self.pos >= self.n:
                self.err("Empty input")
            c = self.s[self.pos]
            if c == '"':
                return self.str()
            if c == '{':
                return self.obj()
            if c == '[':
                return self.arr()
            if c == 't':
                if self.pos + 4 <= self.n and self.s[self.pos:self.pos + 4] == 'true':
                    self.pos += 4
                    return True
            if c == 'f':
                if self.pos + 5 <= self.n and self.s[self.pos:self.pos + 5] == 'false':
                    self.pos += 5
                    return False
            if c == 'n':
                if self.pos + 4 <= self.n and self.s[self.pos:self.pos + 4] == 'null':
                    self.pos += 4
                    return None
            if c == '-' or '0' <= c <= '9':
                return self.num()
            self.err(f"Unexpected '{c}'")

        def str(self):
            self.expect('"')
            out = []
            while self.pos < self.n:
                c = self.s[self.pos]
                if c == '"':
                    self.pos += 1
                    return ''.join(out)
                if c == '\\':
                    self.pos += 1
                    if self.pos >= self.n:
                        self.err("Unexpected end of string")
                    esc = self.s[self.pos]
                    if esc == '"':
                        out.append('"')
                    elif esc == '\\':
                        out.append('\\')
                    elif esc == '/':
                        out.append('/')
                    elif esc == 'b':
                        out.append('\b')
                    elif esc == 'f':
                        out.append('\f')
                    elif esc == 'n':
                        out.append('\n')
                    elif esc == 'r':
                        out.append('\r')
                    elif esc == 't':
                        out.append('\t')
                    elif esc == 'u':
                        self.pos += 1
                        if self.pos + 4 > self.n:
                            self.err("Invalid unicode escape")
                        hx = self.s[self.pos:self.pos + 4]
                        if not all(x in '0123456789abcdefABCDEF' for x in hx):
                            self.err("Invalid hex in unicode escape")
                        cp = int(hx, 16)
                        self.pos += 4
                        if 0xD800 <= cp <= 0xDBFF:
                            if self.pos + 6 <= self.n and self.s[self.pos:self.pos + 2] == '\\u':
                                hx2 = self.s[self.pos + 2:self.pos + 6]
                                if all(x in '0123456789abcdefABCDEF' for x in hx2):
                                    cp2 = int(hx2, 16)
                                    if 0xDC00 <= cp2 <= 0xDFFF:
                                        cp = 0x10000 + (cp - 0xD800) * 0x400 + (cp2 - 0xDC00)
                                        self.pos += 6
