                elif ord(c) < 0x20:
                    self.err("Invalid control character in string")
                else:
                    out.append(c)
                    self.pos += 1
            self.err("Unterminated string")

        def num(self):
            start = self.pos
            if self.pos < self.n and self.s[self.pos] == '-':
                self.pos += 1
            if self.pos >= self.n or self.s[self.pos] < '0' or self.s[self.pos] > '9':
                self.err("Invalid number")
            if self.s[self.pos] == '0':
                self.pos += 1
                if self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.err("Leading zeros not allowed")
            else:
                while self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.pos += 1
            has_frac = False
            if self.pos < self.n and self.s[self.pos] == '.':
                self.pos += 1
                if self.pos >= self.n or self.s[self.pos] < '0' or self.s[self.pos] > '9':
                    self.err("Invalid number")
                has_frac = True
                while self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.pos += 1
            has_exp = False
            if self.pos < self.n and self.s[self.pos] in 'eE':
                self.pos += 1
                if self.pos < self.n and self.s[self.pos] in '+-':
                    self.pos += 1
                if self.pos >= self.n or self.s[self.pos] < '0' or self.s[self.pos] > '9':
                    self.err("Invalid number")
                has_exp = True
                while self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.pos += 1
            sub = self.s[start:self.pos]
            return float(sub) if has_frac or has_exp else int(sub)

        def arr(self):
            self.expect('[')
            self.ws()
            if self.pos < self.n and self.s[self.pos] == ']':
                self.pos += 1
                return []
            items = []
            while True:
                items.append(self.val())
                self.ws()
                if self.pos >= self.n:
                    self.err("Expected ',' or ']'")
                if self.s[self.pos] == ']':
                    self.pos += 1
                    return items
                if self.s[self.pos] == ',':
                    self.pos += 1
                    self.ws()
                    if self.pos < self.n and self.s[self.pos] == ']':
                        self.pos += 1
                        return items
                else:
                    self.err("Expected ',' or ']'")

        def obj(self):
            self.expect('{')
            self.ws()
            if self.pos < self.n and self.s[self.pos] == '}':
                self.pos += 1
                return {}
            obj = {}
            while True:
                key = self.str()
                self.ws()
