                    self.err("Expected ',' or '}'")
                if self.s[self.pos] == '}':
                    self.pos += 1
                    return obj
                if self.s[self.pos] == ',':
                    self.pos += 1
                    self.ws()
                    if self.pos < self.n and self.s[self.pos] == '}':
                        self.pos += 1
                        return obj
                else:
                    self.err("Expected ',' or '}'")

    p = Parser(s)
    result = p.val()
    p.ws()
    if p.pos < p.n:
        raise ValueError("Trailing non-whitespace")
    return result

