            self.expect('{')
            self.skip_ws()
            if self.peek() == '}':
                self.pos += 1
                return {}
            result = {}
            while True:
                self.skip_ws()
                key = self.parse_string()
                self.skip_ws()
                self.expect(':')
                val = self.parse_value()
                result[key] = val
                self.skip_ws()
                ch = self.peek()
                if ch == ',':
                    self.pos += 1
                    self.skip_ws()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                elif ch == '}':
                    self.pos += 1
                    return result
                else:
                    raise ValueError("Expected ',' or '}' in object")

        def parse_array(self):
            self.expect('[')
            self.skip_ws()
            if self.peek() == ']':
                self.pos += 1
                return []
            result = []
            while True:
                self.skip_ws()
                val = self.parse_value()
                result.append(val)
