                ch = self.peek()
                if ch == ',':
                    self.pos += 1
                    self.skip_ws()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                elif ch == ']':
                    self.pos += 1
                    return result
                else:
                    raise ValueError("Expected ',' or ']' in array")

    return Parser(s).parse()

def json_parse(s: str):
    """
    Parses a JSON string strictly according to RFC 8259.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    class Parser:
        def __init__(self, text):
            self.s = text
            self.pos = 0
            self.length = len(text)

        def parse(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Empty input")
            val = self.parse_value()
            self.skip_whitespace()
            if self.pos < self.length:
                raise ValueError("Trailing non-whitespace")
            return val

        def skip_whitespace(self):
            while self.pos < self.length:
                c = self.s[self.pos]
                if c == ' ' or c == '\t' or c == '\n' or c == '\r':
                    self.pos += 1
                else:
                    break

        def peek(self):
            if self.pos < self.length:
                return self.s[self.pos]
            return None

        def advance(self):
            c = self.s[self.pos]
            self.pos += 1
            return c

        def expect(self, char):
            if self.pos >= self.length or self.s[self.pos] != char:
                raise ValueError(f"Expected '{char}'")
            self.pos += 1

        def parse_value(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Unexpected end of input")
            c = self.peek()
            if c == '"':
                return self.parse_string()
            elif c == '{':
                return self.parse_object()
            elif c == '[':
                return self.parse_array()
            elif c == 't':
                return self.parse_true()
            elif c == 'f':
                return self.parse_false()
            elif c == 'n':
                return self.parse_null()
            elif c == '-' or c in '0123456789':
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character '{c}'")

        def parse_string(self):
            self.expect('"')
            chars = []
            while self.pos < self.length:
                c = self.s[self.pos]
                if c == '"':
                    self.pos += 1
                    return ''.join(chars)
                elif c == '\\':
                    self.pos += 1
                    if self.pos >= self.length:
                        raise ValueError("Unexpected end of input in string escape")
                    escape_char = self.s[self.pos]
                    self.pos += 1
                    if escape_char == '"':
                        chars.append('"')
                    elif escape_char == '\\':
                        chars.append('\\')
                    elif escape_char == '/':
                        chars.append('/')
                    elif escape_char == 'b':
                        chars.append('\b')
                    elif escape_char == 'f':
                        chars.append('\f')
                    elif escape_char == 'n':
                        chars.append('\n')
                    elif escape_char == 'r':
                        chars.append('\r')
                    elif escape_char == 't':
                        chars.append('\t')
                    elif escape_char == 'u':
                        if self.pos + 4 > self.length:
                            raise ValueError("Incomplete unicode escape")
                        hex_str = self.s[self.pos:self.pos+4]
                        # Check if valid hex digits
                        for h in hex_str:
                            if h not in '0123456789abcdefABCDEF':
                                raise ValueError("Invalid hex in unicode escape")
                        code_point = int(hex_str, 16)

                        if 0xD800 <= code_point <= 0xDBFF:
                            # High surrogate
                            # Look for low surrogate escape
                            if self.pos + 6 <= self.length and self.s[self.pos:self.pos+2] == '\\u':
                                hex_str_low = self.s[self.pos+2:self.pos+6]
                                low_valid = True
                                for h in hex_str_low:
                                    if h not in '0123456789abcdefABCDEF':
                                        low_valid = False
                                        break
                                if low_valid:
                                    code_point_low = int(hex_str_low, 16)
                                    if 0xDC00 <= code_point_low <= 0xDFFF:
                                        # Combine surrogates
                                        combined = 0x10000 + (code_point - 0xD800) * 0x400 + (code_point_low - 0xDC00)
                                        chars.append(chr(combined))
                                        self.pos += 6 # Skip \uXXXX for low
                                        continue # Continue main loop
                            # If not combined or not found, treat high as single code point
                            chars.append(chr(code_point))
                        elif 0xDC00 <= code_point <= 0xDFFF:
                            # Low surrogate alone
                            chars.append(chr(code_point))
                        else:
                            # Normal character
                            chars.append(chr(code_point))

                        self.pos += 4 # Skip the 4 hex digits of the current escape
                    else:
                        raise ValueError(f"Invalid escape character '{escape_char}'")
                else:
                    # Check for raw control characters
                    if ord(c) < 0x20:
                        raise ValueError("Invalid control character in string")
                    chars.append(c)
                    self.pos += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            # Sign
            if self.pos < self.length and self.s[self.pos] == '-':
                self.pos += 1

            if self.pos >= self.length or self.s[self.pos] not in '0123456789':
                raise ValueError("Invalid number")

            # Integer part
            if self.s[self.pos] == '0':
                self.pos += 1
                # Check for leading zeros (e.g., 01)
                if self.pos < self.length and self.s[self.pos] in '0123456789':
                    raise ValueError("Leading zeros not allowed")
            else:
                self.pos += 1
                while self.pos < self.length and self.s[self.pos] in '0123456789':
                    self.pos += 1

            is_float = False

            # Fractional part
            if self.pos < self.length and self.s[self.pos] == '.':
                is_float = True
                self.pos += 1
                if self.pos >= self.length or self.s[self.pos] not in '0123456789':
                    raise ValueError("Invalid number: expected digit after decimal point")
                while self.pos < self.length and self.s[self.pos] in '0123456789':
                    self.pos += 1

            # Exponent
            if self.pos < self.length and self.s[self.pos] in 'eE':
                is_float = True
                self.pos += 1
                if self.pos < self.length and self.s[self.pos] in '+-':
                    self.pos += 1
                if self.pos >= self.length or self.s[self.pos] not in '0123456789':
                    raise ValueError("Invalid number: expected digit in exponent")
                while self.pos < self.length and self.s[self.pos] in '0123456789':
                    self.pos += 1

            num_str = self.s[start:self.pos]

            if is_float:
                return float(num_str)
            else:
                return int(num_str)

        def parse_true(self):
            if self.s.startswith('true', self.pos):
                self.pos += 4
                return True
            raise ValueError("Invalid literal 'true'")

        def parse_false(self):
            if self.s.startswith('false', self.pos):
                self.pos += 5
                return False
            raise ValueError("Invalid literal 'false'")

        def parse_null(self):
            if self.s.startswith('null', self.pos):
                self.pos += 4
                return None
            raise ValueError("Invalid literal 'null'")

        def parse_object(self):
            self.expect('{')
            d = {}
            self.skip_whitespace()
            if self.peek() == '}':
                self.pos += 1
                return d

            while True:
                self.skip_whitespace()
                if self.peek() != '"':
                    raise ValueError("Expected string key in object")
                key = self.parse_string()

                self.skip_whitespace()
                if self.pos >= self.length or self.s[self.pos] != ':':
                    raise ValueError("Expected ':' after key")
                self.pos += 1

                self.skip_whitespace()
                val = self.parse_value()

                # Duplicate keys: last wins
                d[key] = val

                self.skip_whitespace()
                if self.pos >= self.length:
                    raise ValueError("Unterminated object")
                if self.s[self.pos] == '}':
                    self.pos += 1
                    return d
                if self.s[self.pos] == ',':
                    self.pos += 1
                    # Check for trailing comma
                    self.skip_whitespace()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError("Expected ',' or '}' in object")

        def parse_array(self):
            self.expect('[')
            lst = []
            self.skip_whitespace()
            if self.peek() == ']':
                self.pos += 1
                return lst

            while True:
                self.skip_whitespace()
                val = self.parse_value()
                lst.append(val)

                self.skip_whitespace()
                if self.pos >= self.length:
                    raise ValueError("Unterminated array")
                if self.s[self.pos] == ']':
                    self.pos += 1
                    return lst
                if self.s[self.pos] == ',':
                    self.pos += 1
                    # Check for trailing comma
                    self.skip_whitespace()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError("Expected ',' or ']' in array")

    return Parser(s).parse()

def json_parse(s: str):
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not s.strip(' \t\n\r'):
        raise ValueError("Empty or whitespace-only input")

    class Parser:
        def __init__(self, text):
            self.s = text
            self.pos = 0
            self.n = len(text)

        def peek(self):
            return self.s[self.pos] if self.pos < self.n else None

        def advance(self):
            if self.pos < self.n:
                self.pos += 1
                return self.s[self.pos - 1]
            return None

        def error(self, msg="Invalid JSON"):
            raise ValueError(msg)

        def skip_ws(self):
            while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
                self.pos += 1

        def expect(self, c):
            if self.peek() != c:
                self.error(f"Expected '{c}'")
            return self.advance()

        def parse(self):
            self.skip_ws()
            if self.pos == self.n:
                self.error("Empty input")
            val = self.parse_value()
            self.skip_ws()
            if self.pos != self.n:
                self.error("Trailing non-whitespace")
            return val

        def parse_value(self):
            self.skip_ws()
            c = self.peek()
            if c == '{':
                return self.parse_object()
            elif c == '[':
                return self.parse_array()
            elif c == '"':
                return self.parse_string()
            elif c == 't':
                self.expect('t')
                self.expect('r')
                self.expect('u')
                self.expect('e')
                return True
            elif c == 'f':
                self.expect('f')
                self.expect('a')
                self.expect('l')
                self.expect('s')
                self.expect('e')
                return False
            elif c == 'n':
                self.expect('n')
                self.expect('u')
                self.expect('l')
                self.expect('l')
                return None
            elif c in '-0123456789':
                return self.parse_number()
            else:
                self.error(f"Unexpected character: {c!r}")

        def parse_object(self):
            self.expect('{')
            self.skip_ws()
            d = {}
            if self.peek() == '}':
                self.advance()
                return d
            while True:
                k = self.parse_string()
                self.skip_ws()
                self.expect(':')
                self.skip_ws()
                v = self.parse_value()
                d[k] = v
                self.skip_ws()
                c = self.peek()
                if c == ',':
                    self.advance()
                elif c == '}':
                    self.advance()
                    break
                else:
                    self.error("Expected ',' or '}'")
            return d

        def parse_array(self):
            self.expect('[')
            self.skip_ws()
            lst = []
            if self.peek() == ']':
                self.advance()
                return lst
            while True:
                lst.append(self.parse_value())
                self.skip_ws()
                c = self.peek()
                if c == ',':
                    self.advance()
                elif c == ']':
                    self.advance()
                    break
                else:
                    self.error("Expected ',' or ']'")
