                    elif esc == '\\': chars.append('\\')
                    elif esc == '/': chars.append('/')
                    elif esc == 'b': chars.append('\b')
                    elif esc == 'f': chars.append('\f')
                    elif esc == 'n': chars.append('\n')
                    elif esc == 'r': chars.append('\r')
