                        self.error(f"Invalid escape character: {esc!r}")
                else:
                    chars.append(c)

        def parse_number(self):
            start = self.pos
            if self.peek() == '-':
                self.advance()
            if self.pos >= self.n or self.s[self.pos] not in '0123456789':
                self.error("Invalid number")
            if self.s[self.pos] == '0':
                self.advance()
                if self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.error("Leading zeros not allowed")
            else:
                self.advance()
                while self.pos < self.n and self.s[self.pos] in '0123456789':
