                self.advance()
                if self.pos >= self.n or self.s[self.pos] not in '0123456789':
                    self.error("Invalid number")
                while self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.advance()
            if self.pos < self.n and self.s[self.pos] in 'eE':
                self.advance()
                if self.pos < self.n and self.s[self.pos] in '+-':
                    self.advance()
                if self.pos >= self.n or self.s[self.pos] not in '0123456789':
                    self.error("Invalid number")
                while self.pos < self.n and self.s[self.pos] in '0123456789':
                    self.advance()

            num_str = self.s[start:self.pos]
            if '.' in num_str or 'e' in num_str.lower():
                return float(num_str)
            return int(num_str)

    return Parser(s).parse()

