            else:
                L, c1_min, c1_max = 4, 0x80, 0xBF
        else:
            res.append('\ufffd')
            i += 1
            continue

        k = 1
        valid = True
        while k < L:
            if i + k >= n:
                valid = False
                break
            b_next = b[i + k]
            if b_next < c1_min or b_next > c1_max:
                valid = False
                break
            c1_min, c1_max = 0x80, 0xBF
            k += 1

        if valid:
            if L == 2:
                code = (b0 & 0x1F) << 6 | (b[i+1] & 0x3F)
            elif L == 3:
                code = (b0 & 0x0F) << 12 | (b[i+1] & 0x3F) << 6 | (b[i+2] & 0x3F)
            else:
                code = (b0 & 0x07) << 18 | (b[i+1] & 0x3F) << 12 | (b[i+2] & 0x3F) << 6 | (b[i+3] & 0x3F)
            res.append(chr(code))
            i += L
        else:
            res.append('\ufffd')
            i += k
    return ''.join(res)

def utf8_decode(b: bytes) -> str:
    result = []
    i = 0
    n = len(b)

    while i < n:
        byte = b[i]

        if 0x00 <= byte <= 0x7F:
            # 1-byte sequence (ASCII)
            result.append(chr(byte))
            i += 1
        elif 0x80 <= byte <= 0xBF:
            # Continuation byte where start expected
            result.append('\ufffd')
            i += 1
        elif 0xC0 <= byte <= 0xC1:
            # Invalid start (overlong)
            result.append('\ufffd')
            i += 1
