            if i + 1 < n and 0x80 <= b[i+1] <= 0xBF:
                codepoint = ((byte & 0x1F) << 6) | (b[i+1] & 0x3F)
                result.append(chr(codepoint))
                i += 2
            else:
                # Error: missing or bad continuation
                # Maximal subpart is just the start byte
                result.append('\ufffd')
                i += 1
        elif byte == 0xE0:
            # 3-byte sequence (special 2nd byte)
            if i + 1 < n and 0xA0 <= b[i+1] <= 0xBF:
                if i + 2 < n and 0x80 <= b[i+2] <= 0xBF:
                    codepoint = ((byte & 0x0F) << 12) | ((b[i+1] & 0x3F) << 6) | (b[i+2] & 0x3F)
