def cron_next(expr: str, after: datetime) -> datetime | None:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must contain exactly 5 fields")

    field_ranges = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day-of-month
        (1, 12),   # month
        (0, 7),    # day-of-week
    ]

    field_values = []
    restricted_flags = []

    for i, field_text in enumerate(fields):
        min_v, max_v = field_ranges[i]
        values = set()
        restricted = not field_text.startswith('*')
        restricted_flags.append(restricted)

        for item in field_text.split(','):
            if not item:
                raise ValueError(f"Empty item in field {i}")

            if '/' in item:
                base, step_str = item.split('/')
                if not step_str or not all('0' <= c <= '9' for c in step_str):
                    raise ValueError(f"Invalid step in field {i}: {item}")
                step = int(step_str)
                if step < 1:
                    raise ValueError(f"Step must be >= 1 in field {i}: {item}")

                if base == '*':
                    start, end = min_v, max_v
                elif '-' in base:
                    parts = base.split('-')
                    if len(parts) != 2 or not all('0' <= c <= '9' for c in parts[0]) or not all('0' <= c <= '9' for c in parts[1]):
                        raise ValueError(f"Invalid range in field {i}: {base}")
                    start, end = int(parts[0]), int(parts[1])
                    if start < min_v or end > max_v or start > end:
                        raise ValueError(f"Range out of bounds in field {i}: {base}")
                else:
                    if not all('0' <= c <= '9' for c in base):
                        raise ValueError(f"Invalid value in field {i}: {base}")
                    start = int(base)
                    if start < min_v or start > max_v:
                        raise ValueError(f"Value out of bounds in field {i}: {base}")
                    end = max_v
                values.update(range(start, end + 1, step))

            elif item == '*':
                values.update(range(min_v, max_v + 1))

            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2 or not all('0' <= c <= '9' for c in parts[0]) or not all('0' <= c <= '9' for c in parts[1]):
                    raise ValueError(f"Invalid range in field {i}: {item}")
                start, end = int(parts[0]), int(parts[1])
                if start < min_v or end > max_v or start > end:
                    raise ValueError(f"Range out of bounds in field {i}: {item}")
                values.update(range(start, end + 1))

            else:
                if not all('0' <= c <= '9' for c in item):
                    raise ValueError(f"Invalid value in field {i}: {item}")
                val = int(item)
                if val < min_v or val > max_v:
                    raise ValueError(f"Value out of bounds in field {i}: {item}")
                values.add(val)

        field_values.append(values)

    minute_values = field_values[0]
    hour_values = field_values[1]
    dom_values = field_values[2]
    month_values = field_values[3]
    dow_values = field_values[4]

    # Map cron day-of-week (0=Sun, 1=Mon, ..., 6=Sat, 7=Sun) to Python weekday (0=Mon, ..., 6=Sun)
    # Formula: (cron_dow - 1) % 7
    python_dow_values = {(v - 1) % 7 for v in dow_values}

    dom_restricted = restricted_flags[2]
    dow_restricted = restricted_flags[4]

    limit = after + timedelta(days=3000)
    t = after.replace(second=0, microsecond=0)
    if t <= after:
        t += timedelta(minutes=1)

    while t <= limit:
        if t.minute in minute_values and t.hour in hour_values:
            dom_match = t.day in dom_values
            dow_match = t.weekday() in python_dow_values
            if dom_restricted and dow_restricted:
                day_ok = dom_match or dow_match
            else:
                day_ok = dom_match and dow_match
            if day_ok and t.month in month_values:
                return t
        t += timedelta(minutes=1)

    return None

