    def parse_field(field_str: str, min_val: int, max_val: int) -> list[int]:
        values: set[int] = set()
        parts = field_str.split(',')
        for part in parts:
            if not part:
                raise ValueError("Empty field part")

            step = 1
            if '/' in part:
                base, step_str = part.split('/', 1)
                if not step_str.isascii() or not step_str.isdigit() or int(step_str) < 1:
                    raise ValueError("Invalid step value")
                step = int(step_str)
            else:
                base = part

            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                if base.count('-') != 1:
                    raise ValueError("Invalid range format")
                a, b = base.split('-', 1)
                if not a.isascii() or not a.isdigit() or not b.isascii() or not b.isdigit():
                    raise ValueError("Invalid range values")
                start, end = int(a), int(b)
                if start > end:
                    raise ValueError("Range start cannot exceed end")
            elif base.isascii() and base.isdigit():
                start, end = int(base), int(base)
            else:
                raise ValueError("Invalid field item")

            if start < min_val or end > max_val:
                raise ValueError("Value out of allowed range")

            for v in range(start, end + 1, step):
                values.add(v)
        return sorted(values)

    minute_vals = parse_field(fields[0], 0, 59)
    hour_vals = parse_field(fields[1], 0, 23)
    dom_vals = parse_field(fields[2], 1, 31)
    month_vals = parse_field(fields[3], 1, 12)

    # Parse DOW with max 7, then normalize 7 to 0 (Sunday)
    dow_raw = parse_field(fields[4], 0, 7)
    dow_vals = sorted(set(0 if v == 7 else v for v in dow_raw))

    restricted_dom = not fields[2].startswith('*')
    restricted_dow = not fields[4].startswith('*')

    end_time = after + timedelta(days=3000)
    if end_time < after:
        # Guard against pathological datetime arithmetic, though unlikely with positive days
        end_time = after + timedelta(days=3000)

    # Start searching strictly after `after`, at the next minute boundary
    curr = after.replace(second=0, microsecond=0) + timedelta(seconds=1)
    if curr > end_time:
        return None

    month_set = set(month_vals)
    dom_set = set(dom_vals)
    dow_set = set(dow_vals)

    while curr <= end_time:
        d = curr.date()

        # Skip months not in expression
        if d.month not in month_set:
            curr = (d + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check day constraints
        # Python weekday(): Mon=0, ..., Sun=6
        # Cron DOW:       Sun=0, Mon=1, ..., Sat=6
        cron_dow = (d.weekday() + 1) % 7
        dom = d.day

        dom_ok = dom in dom_set
        dow_ok = cron_dow in dow_set

        if restricted_dom and restricted_dow:
            day_ok = dom_ok or dow_ok
        else:
            day_ok = dom_ok and dow_ok

        if not day_ok:
            curr = (d + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Find earliest valid hour and minute on this day
        start_h = curr.hour
        start_m = curr.minute
        found = False

        for h in hour_vals:
            if h < start_h:
                continue
            for m in minute_vals:
                if h == start_h and m < start_m:
                    continue
                return curr.replace(hour=h, minute=m, second=0)
            start_m = 0  # Reset minute search for subsequent hours

        # No valid time on this day, advance to next day
        curr = (d + timedelta(days=1)).replace(hour=0, minute=0)

    return None

