                    raise ValueError(f"Start must be <= end in range in field: {text}")
                start, end = a, b
            else:
                try:
                    n = int(base)
                except ValueError:
                    raise ValueError(f"Invalid number in field: {text}")
                start, end = n, max_val

            for val in range(start, end + 1, step):
                if is_dow and val == 7:
                    val = 0
                if not (min_val <= val <= max_val):
                    raise ValueError(f"Value {val} out of range in field: {text}")
                values.add(val)

        if not values:
            raise ValueError(f"No valid values in field: {text}")
        return restricted, sorted(values)

    minute_restricted, minutes = parse_field(parts[0], 0, 59)
    hour_restricted, hours = parse_field(parts[1], 0, 23)
    dom_restricted, doms = parse_field(parts[2], 1, 31)
    month_restricted, months = parse_field(parts[3], 1, 12)
    dow_restricted, dows = parse_field(parts[4], 0, 7, is_dow=True)

    # Start strictly after `after`, rounded down to the minute
    current = (after + datetime.timedelta(seconds=1)).replace(second=0, microsecond=0)
    limit = after + datetime.timedelta(days=3000)

    while current <= limit:
        # Check month
        if current.month not in months:
            current = current.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            found_month = False
            for m in months:
                if m > current.month:
                    current = current.replace(month=m)
                    found_month = True
                    break
            if not found_month:
                current = current.replace(year=current.year + 1, month=1)
            continue

        # Check day (DOM/DOW logic)
        python_wd = current.weekday()  # 0=Mon, ..., 6=Sun
        cron_wd = (python_wd + 1) % 7  # 0=Sun, 1=Mon, ..., 6=Sat
        dom_match = current.day in doms
        dow_match = cron_wd in dows

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            current += datetime.timedelta(days=1)
            continue

        # Check hour
        if current.hour not in hours:
            current = current.replace(minute=0, second=0, microsecond=0)
            found_hour = False
            for h in hours:
                if h > current.hour:
                    current = current.replace(hour=h)
                    found_hour = True
                    break
            if not found_hour:
                current += datetime.timedelta(days=1)
            continue

        # Check minute
        if current.minute not in minutes:
            current = current.replace(second=0, microsecond=0)
            found_min = False
            for m in minutes:
                if m > current.minute:
                    current = current.replace(minute=m)
                    found_min = True
                    break
            if not found_min:
                current += datetime.timedelta(days=1)
            continue

        # All fields match
        return current

    return None

