                tokens.append(('INT', int(s[i:j])))
                i = j
            elif s[i] == 'x':
                tokens.append(('X', None))
                i += 1
            elif s[i] == '+':
                tokens.append(('PLUS', None))
                i += 1
            elif s[i] == '-':
                tokens.append(('MINUS', None))
                i += 1
            elif s[i] == '*':
                tokens.append(('STAR', None))
                i += 1
            elif s[i] == '^':
                tokens.append(('CARET', None))
                i += 1
            elif s[i] == '(':
                tokens.append(('LPAREN', None))
                i += 1
            elif s[i] == ')':
                tokens.append(('RPAREN', None))
                i += 1
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected_type=None):
            tok = self.peek()
            if tok is None:
                raise ValueError("Unexpected end of input")
            if expected_type and tok[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {tok}")
            self.pos += 1
            return tok

        def add_poly(self, p1, p2):
            res = dict(p1)
            for d, c in p2.items():
                res[d] = res.get(d, 0) + c
            return {d: c for d, c in res.items() if c != 0}

        def sub_poly(self, p1, p2):
            res = dict(p1)
            for d, c in p2.items():
                res[d] = res.get(d, 0) - c
            return {d: c for d, c in res.items() if c != 0}

        def mul_poly(self, p1, p2):
            res = {}
            for d1, c1 in p1.items():
                for d2, c2 in p2.items():
                    res[d1 + d2] = res.get(d1 + d2, 0) + c1 * c2
            return {d: c for d, c in res.items() if c != 0}

        def pow_poly(self, p, n):
            if n == 0:
                return {0: 1}
            res = {0: 1}
            for _ in range(n):
                res = self.mul_poly(res, p)
            return res

        def neg_poly(self, p):
            return {d: -c for d, c in p.items() if c != 0}

        def parse_expr(self):
            res = self.parse_term()
            while self.peek() and self.peek()[0] in ('PLUS', 'MINUS'):
                op = self.consume()[0]
                rhs = self.parse_term()
                if op == 'PLUS':
                    res = self.add_poly(res, rhs)
                else:
                    res = self.sub_poly(res, rhs)
            return res

        def parse_term(self):
            res = self.parse_unary()
            while self.peek() and self.peek()[0] == 'STAR':
                self.consume()
                rhs = self.parse_unary()
                res = self.mul_poly(res, rhs)
            return res

        def parse_unary(self):
            if self.peek() and self.peek()[0] == 'MINUS':
                self.consume()
                return self.neg_poly(self.parse_unary())
            return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            if self.peek() and self.peek()[0] == 'CARET':
                self.consume()
                exp_tok = self.consume('INT')
                exp = exp_tok[1]
                if exp > 20:
                    raise ValueError("Exponent > 20")
                return self.pow_poly(base, exp)
