        def parse_atom(self):
            tok = self.peek()
            if tok is None:
                raise ValueError("Unexpected end of input in atom")
            if tok[0] == 'INT':
                self.consume()
                return {0: int(tok[1])}
            elif tok[0] == 'X':
                self.consume()
                return {1: 1}
            elif tok[0] == 'LPAREN':
                self.consume()
                res = self.parse_expr()
                self.consume('RPAREN')
                return res
            else:
                raise ValueError(f"Unexpected token {tok}")

