        return "0"

    terms = []
    for d in sorted(poly.keys(), reverse=True):
        c = poly[d]
        if c == 0:
            continue
        if d == 0:
            term_str = str(c)
        elif d == 1:
            if c == 1:
                term_str = "x"
            elif c == -1:
                term_str = "-x"
            else:
                term_str = f"{c}x"
        else:
            if c == 1:
                term_str = f"x^{d}"
            elif c == -1:
                term_str = f"-x^{d}"
            else:
                term_str = f"{c}x^{d}"
        terms.append((term_str, c))

    if not terms:
        return "0"

    res = terms[0][0]
    for term_str, c in terms[1:]:
        if c > 0:
            res += f" + {term_str.lstrip('-')}"
        else:
            res += f" - {term_str.lstrip('-')}"
    return res

def poly_expand(expr: str) -> str:
    # Tokenizer
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j])))
                i = j
            elif s[i] == 'x':
                tokens.append(('X', 'x'))
                i += 1
            elif s[i] in '+-*/^()':
                tokens.append(('OP', s[i]))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {s[i]}")
        return tokens

    # Polynomial operations
    # Represent polynomial as list of coefficients [c0, c1, c2, ...] where ci is coeff of x^i
    def poly_add(a, b):
        n = max(len(a), len(b))
        res = [0] * n
        for i in range(len(a)): res[i] += a[i]
        for i in range(len(b)): res[i] += b[i]
        return res

    def poly_sub(a, b):
        n = max(len(a), len(b))
        res = [0] * n
        for i in range(len(a)): res[i] += a[i]
        for i in range(len(b)): res[i] -= b[i]
        return res

    def poly_mul(a, b):
        if not a or not b: return [0]
        res = [0] * (len(a) + len(b) - 1)
        for i, ca in enumerate(a):
            if ca == 0: continue
            for j, cb in enumerate(b):
                res[i+j] += ca * cb
        return res

    def poly_neg(a):
        return [-x for x in a]

    def poly_pow(a, n):
        if n == 0: return [1]
        if n == 1: return list(a)
        res = [1]
        base = list(a)
        exp = n
        while exp > 0:
            if exp % 2 == 1:
                res = poly_mul(res, base)
            base = poly_mul(base, base)
            exp //= 2
        return res

    # Parser
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected_type=None, expected_val=None):
            if self.pos >= len(self.tokens):
                raise ValueError("Unexpected end of input")
            tok = self.tokens[self.pos]
            if expected_type and tok[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {tok}")
            if expected_val and tok[1] != expected_val:
                raise ValueError(f"Expected {expected_val}, got {tok}")
            self.pos += 1
            return tok

        def parse_expr(self):
            left = self.parse_term()
            while True:
                tok = self.peek()
                if tok and tok[0] == 'OP' and tok[1] in ('+', '-'):
                    self.consume()
                    right = self.parse_term()
                    if tok[1] == '+':
                        left = poly_add(left, right)
                    else:
                        left = poly_sub(left, right)
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_unary()
            while True:
                tok = self.peek()
                if tok and tok[0] == 'OP' and tok[1] == '*':
                    self.consume()
                    right = self.parse_unary()
                    left = poly_mul(left, right)
                else:
                    break
            return left

        def parse_unary(self):
            tok = self.peek()
            if tok and tok[0] == 'OP' and tok[1] == '-':
                self.consume()
                operand = self.parse_unary()
                return poly_neg(operand)
            else:
                return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            tok = self.peek()
            if tok and tok[0] == 'OP' and tok[1] == '^':
                self.consume()
                exp_tok = self.peek()
                if not exp_tok or exp_tok[0] != 'INT':
                    raise ValueError("Expected integer exponent")
                self.consume()
                exp = exp_tok[1]
                if exp > 20:
                    raise ValueError("Exponent too large")
                base = poly_pow(base, exp)
            return base

        def parse_atom(self):
            tok = self.peek()
            if not tok:
                raise ValueError("Unexpected end of input")

            if tok[0] == 'INT':
                self.consume()
                return [tok[1]]

            if tok[1] == 'x':
                self.consume()
                return [0, 1]

            if tok[0] == 'OP' and tok[1] == '(':
                self.consume()
                res = self.parse_expr()
                close = self.peek()
                if not close or close[0] != 'OP' or close[1] != ')':
                    raise ValueError("Expected ')'")
                self.consume()
                return res

            raise ValueError(f"Unexpected token: {tok}")

    # Main execution
    try:
        tokens = tokenize(expr)
        parser = Parser(tokens)
        result_poly = parser.parse_expr()

        # Check if all tokens consumed
        if parser.pos != len(tokens):
            raise ValueError("Unexpected tokens remaining")

        # Format result
        # Find highest degree
        max_deg = -1
        for i in range(len(result_poly) - 1, -1, -1):
            if result_poly[i] != 0:
                max_deg = i
                break

        if max_deg == -1:
            return "0"

        terms = []
        for d in range(max_deg, -1, -1):
            coeff = result_poly[d]
            if coeff == 0:
                continue

            abs_c = abs(coeff)
            if d == 0:
                term_str = str(abs_c)
            elif d == 1:
                if abs_c == 1:
                    term_str = "x"
                else:
                    term_str = f"{abs_c}x"
            else:
                if abs_c == 1:
                    term_str = f"x^{d}"
                else:
                    term_str = f"{abs_c}x^{d}"

            if coeff < 0:
                if not terms:
                    terms.append("-" + term_str)
                else:
                    terms.append(" - " + term_str)
            else:
                if not terms:
                    terms.append(term_str)
                else:
                    terms.append(" + " + term_str)

        return "".join(terms)

    except ValueError:
        raise
    except Exception as e:
        raise ValueError(str(e))

def poly_expand(expr: str) -> str:
    def tokenize(s: str) -> list:
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
            elif s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('NUM', int(s[i:j])))
                i = j
            elif s[i] == 'x':
                tokens.append('x')
                i += 1
            elif s[i] in '+-*/^()':
                tokens.append(s[i])
                i += 1
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        return tokens

    def add_poly(p1: dict, p2: dict) -> dict:
        res = dict(p1)
        for deg, coeff in p2.items():
            res[deg] = res.get(deg, 0) + coeff
        return {d: c for d, c in res.items() if c != 0}

    def sub_poly(p1: dict, p2: dict) -> dict:
        res = dict(p1)
        for deg, coeff in p2.items():
            res[deg] = res.get(deg, 0) - coeff
        return {d: c for d, c in res.items() if c != 0}

    def neg_poly(p: dict) -> dict:
        return {d: -c for d, c in p.items() if c != 0}

    def mul_poly(p1: dict, p2: dict) -> dict:
        if not p1 or not p2:
            return {}
        res = {}
        for d1, c1 in p1.items():
            for d2, c2 in p2.items():
                d = d1 + d2
                res[d] = res.get(d, 0) + c1 * c2
        return {d: c for d, c in res.items() if c != 0}

    def pow_poly(p: dict, n: int) -> dict:
        if n == 0:
            return {0: 1}
        res = {0: 1}
        for _ in range(n):
            res = mul_poly(res, p)
        return res

    def format_poly(p: dict) -> str:
        if not p:
            return "0"
        terms = sorted(p.items(), key=lambda x: x[0], reverse=True)
        parts = []
        for i, (deg, coeff) in enumerate(terms):
            if i == 0:
                if coeff < 0:
                    parts.append("-")
                    coeff = -coeff
            else:
                if coeff < 0:
                    parts.append(" - ")
                    coeff = -coeff
                else:
                    parts.append(" + ")

            if deg == 0:
                parts.append(str(coeff))
            elif deg == 1:
                parts.append("x" if coeff == 1 else f"{coeff}x")
            else:
                parts.append(f"x^{deg}" if coeff == 1 else f"{coeff}x^{deg}")
        return "".join(parts)

    class Parser:
        def __init__(self, tokens: list):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected=None):
            tok = self.peek()
            if expected is not None and tok != expected:
                raise ValueError(f"Expected {expected}, got {tok}")
            self.pos += 1
            return tok

        def parse(self) -> dict:
            poly = self.parse_expr()
            if self.pos != len(self.tokens):
                raise ValueError("Unexpected tokens at end of input")
            return poly

        def parse_expr(self) -> dict:
            poly = self.parse_term()
            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.parse_term()
                if op == '+':
                    poly = add_poly(poly, right)
                else:
                    poly = sub_poly(poly, right)
            return poly

        def parse_term(self) -> dict:
            poly = self.parse_unary()
            while self.peek() == '*':
                self.consume()
                right = self.parse_unary()
                poly = mul_poly(poly, right)
            return poly

        def parse_unary(self) -> dict:
            if self.peek() == '-':
                self.consume()
                poly = self.parse_unary()
                return neg_poly(poly)
            return self.parse_power()

        def parse_power(self) -> dict:
            poly = self.parse_atom()
            if self.peek() == '^':
                self.consume()
                exp_tok = self.consume()
                if not isinstance(exp_tok, tuple) or exp_tok[0] != 'NUM':
                    raise ValueError("Expected integer exponent")
                exp = exp_tok[1]
                if exp > 20:
                    raise ValueError("Exponent must be <= 20")
                poly = pow_poly(poly, exp)
            return poly

        def parse_atom(self) -> dict:
            tok = self.peek()
            if tok == '(':
                self.consume()
                poly = self.parse_expr()
                self.consume(')')
                return poly
            elif tok == 'x':
                self.consume()
                return {1: 1}
            elif isinstance(tok, tuple) and tok[0] == 'NUM':
                self.consume()
                return {0: tok[1]}
            else:
                raise ValueError(f"Unexpected token: {tok}")

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty input")
    parser = Parser(tokens)
    poly = parser.parse()
    return format_poly(poly)

