        def format_poly(self, p):
            while len(p) > 1 and p[-1] == 0:
                p.pop()
            if p[0] == 0 and len(p) == 1:
                return "0"

            res_parts = []
            for k in range(len(p)-1, -1, -1):
                c = p[k]
                if c == 0:
