                    var_str = "x"
                else:
                    coeff_str = "" if abs_c == 1 else str(abs_c)
                    var_str = f"x^{k}"

                term = coeff_str + var_str

                if not res_parts:
                    if is_neg:
                        res_parts.append("-" + term)
                    else:
                        res_parts.append(term)
                else:
                    if is_neg:
                        res_parts.append("- " + term)
                    else:
                        res_parts.append("+ " + term)

            return "".join(res_parts)

    parser = Parser(expr)
    poly = parser.parse_expr()
    parser.skip_ws()
    if parser.pos != parser.n:
        raise ValueError("Unexpected trailing characters")
    return parser.format_poly(poly)

