    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def peek(self):
            if self.pos < self.n:
                return self.s[self.pos]
            return None

        def advance(self):
            self.pos += 1

        def skip_spaces(self):
            while self.pos < self.n and self.s[self.pos].isspace():
                self.pos += 1

        def parse_int(self) -> str:
            if self.pos >= self.n or not self.s[self.pos].isdigit():
                raise ValueError("Expected integer")
            start = self.pos
            while self.pos < self.n and self.s[self.pos].isdigit():
                self.pos += 1
            return self.s[start:self.pos]

        def parse_expr(self):
            left = self.parse_term()
            while True:
                self.skip_spaces()
                if self.pos >= self.n:
                    break
                ch = self.s[self.pos]
                if ch in ('+', '-'):
                    self.advance()
                    right = self.parse_term()
                    if ch == '+':
                        left = poly_add(left, right)
                    else:
                        left = poly_sub(left, right)
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_unary()
            while True:
                self.skip_spaces()
                if self.pos >= self.n:
                    break
                if self.s[self.pos] == '*':
                    self.advance()
                    right = self.parse_unary()
                    left = poly_mul(left, right)
                else:
                    break
            return left

        def parse_unary(self):
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == '-':
                self.advance()
                return poly_neg(self.parse_unary())
            return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            self.skip_spaces()
            if self.pos < self.n and self.s[self.pos] == '^':
                self.advance()
                self.skip_spaces()
                exp_str = self.parse_int()
                exp = int(exp_str)
                if exp > 20:
                    raise ValueError("Exponent too large")
                return poly_pow(base, exp)
            return base

        def parse_atom(self):
            self.skip_spaces()
            if self.pos >= self.n:
                raise ValueError("Unexpected end of input")
            ch = self.s[self.pos]
            if ch.isdigit():
                num_str = self.parse_int()
                return {0: int(num_str)}
            elif ch == 'x':
                self.advance()
                return {1: 1}
            elif ch == '(':
                self.advance()
                result = self.parse_expr()
                self.skip_spaces()
                if self.pos >= self.n or self.s[self.pos] != ')':
                    raise ValueError("Expected ')'")
                self.advance()
                return result
            else:
                raise ValueError(f"Unexpected character: '{ch}'")

