        for d, c in p1.items():
            res[d] = res.get(d, 0) + c
        for d, c in p2.items():
            res[d] = res.get(d, 0) + c
        return {d: c for d, c in res.items() if c != 0}

    def poly_sub(p1, p2):
        res = {}
        for d, c in p1.items():
            res[d] = res.get(d, 0) + c
        for d, c in p2.items():
            res[d] = res.get(d, 0) - c
        return {d: c for d, c in res.items() if c != 0}

    def poly_neg(p):
        return {d: -c for d, c in p.items() if c != 0}

    def poly_mul(p1, p2):
        res = {}
        for d1, c1 in p1.items():
            for d2, c2 in p2.items():
                res[d1 + d2] = res.get(d1 + d2, 0) + c1 * c2
        return {d: c for d, c in res.items() if c != 0}

    def poly_pow(p, n):
        if n == 0:
            return {0: 1}
        res = {0: 1}
        for _ in range(n):
            res = poly_mul(res, p)
        return res

