        for d in sorted(p.keys(), reverse=True):
            c = p[d]
            if d == 0:
                coeff_str = str(abs(c))
            elif d == 1:
                coeff_str = "x" if abs(c) == 1 else f"{abs(c)}x"
            else:
                coeff_str = f"x^{d}" if abs(c) == 1 else f"{abs(c)}x^{d}"

            if c < 0:
                if not terms:
                    terms.append("-" + coeff_str)
                else:
                    terms.append(" - " + coeff_str)
            else:
                if not terms:
                    terms.append(coeff_str)
                else:
                    terms.append(" + " + coeff_str)
        return "".join(terms)

    parser = Parser(expr)
    result = parser.parse_expr()
    parser.skip_spaces()
    if parser.pos != parser.n:
        raise ValueError("Unexpected trailing characters")
    return format_poly(result)

def poly_expand(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i].isspace():
            i += 1
            continue
        if expr[i].isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('INT', int(expr[i:j])))
            i = j
        elif expr[i] == 'x':
            tokens.append(('X', 'x'))
            i += 1
        elif expr[i] == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif expr[i] == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif expr[i] == '*':
            tokens.append(('STAR', '*'))
            i += 1
        elif expr[i] == '^':
            tokens.append(('CARET', '^'))
            i += 1
        elif expr[i] == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif expr[i] == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {expr[i]}")
    tokens.append(('EOF', None))

    pos = [0]

    def peek():
        return tokens[pos[0]]

    def consume(expected_type=None):
        tok = tokens[pos[0]]
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]}")
        pos[0] += 1
        return tok

    def poly_add(p1, p2):
        res = dict(p1)
        for d, c in p2.items():
            res[d] = res.get(d, 0) + c
        return {d: c for d, c in res.items() if c != 0}

    def poly_sub(p1, p2):
        res = dict(p1)
        for d, c in p2.items():
            res[d] = res.get(d, 0) - c
        return {d: c for d, c in res.items() if c != 0}

    def poly_mul(p1, p2):
        res = {}
        for d1, c1 in p1.items():
            for d2, c2 in p2.items():
                d = d1 + d2
                c = c1 * c2
                res[d] = res.get(d, 0) + c
        return {d: c for d, c in res.items() if c != 0}

    def poly_pow(p, n):
        if n == 0:
            return {0: 1}
        if not p:
            return {}
        res = {0: 1}
        for _ in range(n):
            res = poly_mul(res, p)
        return res

    def parse_expr():
        left = parse_term()
        while peek()[0] in ('PLUS', 'MINUS'):
            op = consume()[0]
            right = parse_term()
            if op == 'PLUS':
                left = poly_add(left, right)
            else:
                left = poly_sub(left, right)
        return left

    def parse_term():
        left = parse_unary()
        while peek()[0] == 'STAR':
            consume()
            right = parse_unary()
            left = poly_mul(left, right)
        return left

    def parse_unary():
        if peek()[0] == 'MINUS':
            consume()
            p = parse_unary()
            return {d: -c for d, c in p.items()}
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek()[0] == 'CARET':
            consume()
            exp_tok = consume('INT')
            exp = exp_tok[1]
            if exp > 20:
                raise ValueError("Exponent too large")
            return poly_pow(base, exp)
        return base

    def parse_atom():
        tok = peek()
        if tok[0] == 'INT':
            consume()
            return {0: tok[1]}
        elif tok[0] == 'X':
            consume()
            return {1: 1}
        elif tok[0] == 'LPAREN':
            consume()
            p = parse_expr()
            if peek()[0] != 'RPAREN':
                raise ValueError("Expected ')'")
            consume()
            return p
        else:
            raise ValueError(f"Unexpected token: {tok}")

    poly = parse_expr()
    if peek()[0] != 'EOF':
        raise ValueError("Unexpected tokens after expression")

    if not poly:
        return "0"

    degrees = sorted(poly.keys(), reverse=True)
    terms = []
    for i, d in enumerate(degrees):
        c = poly[d]
        if c == 0:
            continue
        if i == 0:
            if c < 0:
                sign = "-"
                c = -c
            else:
                sign = ""
        else:
            if c < 0:
                sign = " - "
                c = -c
            else:
                sign = " + "

        if d == 0:
            term_str = str(c)
        elif d == 1:
            term_str = "x" if c == 1 else f"{c}x"
        else:
            term_str = f"x^{d}" if c == 1 else f"{c}x^{d}"
        terms.append(sign + term_str)

    return "".join(terms)

def poly_expand(expr: str) -> str:
    class PolyParser:
        def __init__(self, s: str):
            self.s = s
            self.pos = 0
            self.n = len(s)

        def peek(self):
            if self.pos < self.n:
                return self.s[self.pos]
            return None

        def consume(self):
            ch = self.s[self.pos]
            self.pos += 1
            return ch

        def skip_spaces(self):
            while self.pos < self.n and self.s[self.pos] == ' ':
                self.pos += 1

        def parse_expr(self):
            left = self.parse_term()
            while True:
                self.skip_spaces()
                if self.peek() in ('+', '-'):
                    op = self.consume()
                    right = self.parse_term()
                    if op == '+':
                        left = poly_add(left, right)
                    else:
                        left = poly_sub(left, right)
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_unary()
            while True:
                self.skip_spaces()
                if self.peek() == '*':
                    self.consume()
                    right = self.parse_unary()
                    left = poly_mul(left, right)
                else:
                    break
            return left

        def parse_unary(self):
            self.skip_spaces()
            if self.peek() == '-':
                self.consume()
                return poly_neg(self.parse_unary())
            return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            self.skip_spaces()
            if self.peek() == '^':
                self.consume()
                self.skip_spaces()
                exp = self.parse_int()
                if exp < 0:
                    raise ValueError("Negative exponent not allowed")
                if exp > 20:
                    raise ValueError("Exponent too large")
                base = poly_pow(base, exp)
            return base

        def parse_atom(self):
            self.skip_spaces()
            ch = self.peek()
            if ch is None:
                raise ValueError("Unexpected end of input")
            if ch.isdigit():
                return poly_from_int(self.parse_int())
            elif ch == 'x':
                self.consume()
                return poly_from_x()
            elif ch == '(':
                self.consume()
                expr = self.parse_expr()
                self.skip_spaces()
                if self.peek() != ')':
                    raise ValueError("Expected ')'")
                self.consume()
                return expr
            else:
                raise ValueError(f"Unexpected character: {ch}")

        def parse_int(self):
            if self.pos >= self.n or not self.s[self.pos].isdigit():
                raise ValueError("Expected integer")
            start = self.pos
            while self.pos < self.n and self.s[self.pos].isdigit():
                self.pos += 1
            return int(self.s[start:self.pos])

    def poly_add(p1, p2):
        res = p1.copy()
        for d, c in p2.items():
            res[d] = res.get(d, 0) + c
        return {d: c for d, c in res.items() if c != 0}

    def poly_sub(p1, p2):
        res = p1.copy()
        for d, c in p2.items():
            res[d] = res.get(d, 0) - c
        return {d: c for d, c in res.items() if c != 0}

    def poly_neg(p):
        return {d: -c for d, c in p.items() if c != 0}

    def poly_mul(p1, p2):
        if not p1 or not p2:
            return {}
        res = {}
        for d1, c1 in p1.items():
            for d2, c2 in p2.items():
                d = d1 + d2
                res[d] = res.get(d, 0) + c1 * c2
        return {d: c for d, c in res.items() if c != 0}

    def poly_pow(p, exp):
        if exp == 0:
            return {0: 1}
        if exp == 1:
            return p.copy()
        res = {0: 1}
        base = p.copy()
        e = exp
        while e > 0:
            if e % 2 == 1:
                res = poly_mul(res, base)
            base = poly_mul(base, base)
            e //= 2
        return res

    def poly_from_int(n):
        return {0: n} if n != 0 else {}

    def poly_from_x():
        return {1: 1}

    def format_poly(p):
        if not p:
            return "0"
        terms = sorted(p.items(), key=lambda x: x[0], reverse=True)
        res = []
        for d, c in terms:
            if d == 0:
                s = str(c)
            elif d == 1:
                if c == 1: s = "x"
                elif c == -1: s = "-x"
                else: s = f"{c}x"
            else:
                if c == 1: s = f"x^{d}"
                elif c == -1: s = f"-x^{d}"
                else: s = f"{c}x^{d}"

            if not res:
                res.append(s)
            else:
                if c > 0:
                    res.append(" + " + s)
                else:
                    res.append(" - " + s[1:])
        return "".join(res)

    parser = PolyParser(expr)
    p = parser.parse_expr()
    parser.skip_spaces()
    if parser.pos != parser.n:
        raise ValueError("Unexpected trailing characters")
    return format_poly(p)

from fractions import Fraction

def rational_eval(expr: str) -> str:
    def tokenize(s: str):
        tokens = []
        i, n = 0, len(s)
        while i < n:
            if s[i].isspace():
                i += 1
            elif s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j])))
                i = j
            elif s[i] in '+-*/^()':
                tokens.append((s[i], s[i]))
                i += 1
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        tokens.append(('EOF', None))
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos]

        def consume(self, expected=None):
            tok = self.tokens[self.pos]
            if expected is not None and tok[1] != expected:
                raise ValueError(f"Expected '{expected}', got '{tok[1]}'")
            self.pos += 1
            return tok

        def atom(self):
            tok = self.peek()
            if tok[1] == '(':
                self.consume('(')
                val = self.expr()
                if self.peek()[1] != ')':
                    raise ValueError("Expected ')'")
                self.consume(')')
                return val
            elif tok[0] == 'INT':
                self.consume()
                return Fraction(tok[1])
            else:
                raise ValueError("Unexpected token in atom")

        def power(self):
            base = self.atom()
            if self.peek()[1] == '^':
                self.consume('^')
                exp = self.unary()
                if exp.denominator != 1:
                    raise ValueError("Exponent must be an integer")
                exp_int = exp.numerator
                if base == 0 and exp_int == 0:
                    return Fraction(1)
                if base == 0 and exp_int < 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return base ** exp_int
            return base

        def unary(self):
            if self.peek()[1] == '-':
                self.consume('-')
                return -self.unary()
            return self.power()

        def term(self):
            left = self.unary()
            while self.peek()[1] in ('*', '/'):
                op = self.consume()[1]
                right = self.unary()
                if op == '*':
                    left *= right
                else:
                    left /= right
            return left

        def expr(self):
            left = self.term()
            while self.peek()[1] in ('+', '-'):
                op = self.consume()[1]
                right = self.term()
                if op == '+':
                    left += right
                else:
                    left -= right
            return left

    tokens = tokenize(expr)
    parser = Parser(tokens)
    result = parser.expr()
    if parser.pos != len(tokens):
        raise ValueError("Unexpected tokens after expression")

    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

import math

def rational_eval(expr: str) -> str:
    s = expr
    pos = 0
    n = len(s)

    def skip_spaces():
        nonlocal pos
        while pos < n and s[pos] == ' ':
            pos += 1

    def make_rational(num, den):
        if den == 0:
            raise ZeroDivisionError("Division by zero")
        if den < 0:
            num, den = -num, -den
        g = math.gcd(num, den)
        return (num // g, den // g)

    def add(a, b):
        return make_rational(a[0]*b[1] + b[0]*a[1], a[1]*b[1])

    def sub(a, b):
        return make_rational(a[0]*b[1] - b[0]*a[1], a[1]*b[1])

    def mul(a, b):
        return make_rational(a[0]*b[0], a[1]*b[1])

    def div(a, b):
        if b[0] == 0:
            raise ZeroDivisionError("Division by zero")
        return make_rational(a[0]*b[1], a[1]*b[0])

    def neg(a):
        return (-a[0], a[1])

    def rational_pow(base, exp):
        if base[0] == 0:
            if exp < 0:
                raise ZeroDivisionError("0 to a negative power")
            return (1, 1)  # 0^0 = 1
        if exp >= 0:
            return make_rational(base[0]**exp, base[1]**exp)
        else:
            return make_rational(base[1]**(-exp), base[0]**(-exp))

    def parse_atom():
        skip_spaces()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        c = s[pos]
        if c == '(':
            pos += 1
            val = parse_expr()
            skip_spaces()
            if pos >= n or s[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return val
        elif c.isdigit():
            start = pos
            while pos < n and s[pos].isdigit():
                pos += 1
            return make_rational(int(s[start:pos]), 1)
        else:
            raise ValueError(f"Unexpected character: {c}")

    def parse_power():
        base = parse_atom()
        skip_spaces()
        if pos < n and s[pos] == '^':
            pos += 1
            exp = parse_unary()
            if exp[1] != 1:
                raise ValueError("Exponent must be an integer")
            return rational_pow(base, exp[0])
        return base

    def parse_unary():
        skip_spaces()
        if pos < n and s[pos] == '-':
            pos += 1
            return neg(parse_unary())
        return parse_power()

    def parse_term():
        left = parse_unary()
        while True:
            skip_spaces()
            if pos >= n: break
            op = s[pos]
            if op in ('*', '/'):
                pos += 1
                right = parse_unary()
                left = mul(left, right) if op == '*' else div(left, right)
            else:
                break
        return left

    def parse_expr():
        left = parse_term()
        while True:
            skip_spaces()
            if pos >= n: break
            op = s[pos]
            if op in ('+', '-'):
                pos += 1
                right = parse_term()
                left = add(left, right) if op == '+' else sub(left, right)
            else:
                break
        return left

    result = parse_expr()
    skip_spaces()
    if pos < n:
        raise ValueError("Unexpected trailing characters")

    if result[1] == 1:
        return str(result[0])
    else:
        return f"{result[0]}/{result[1]}"

