    pos = 0

    def skip():
        nonlocal pos
        while pos < n and s[pos] == ' ':
            pos += 1

    def peek():
        skip()
        return s[pos] if pos < n else None

    def consume():
        nonlocal pos
        skip()
        if pos >= n:
            return None
        ch = s[pos]
        pos += 1
        return ch

    def normalize(num, den):
        if den < 0:
            num, den = -num, -den
        g = math.gcd(abs(num), den)
        return num // g, den // g

    def to_frac(val):
        return (val, 1)

    def add(a, b):
        n1, d1 = a
        n2, d2 = b
        return normalize(n1 * d2 + n2 * d1, d1 * d2)

    def sub(a, b):
        n1, d1 = a
        n2, d2 = b
        return normalize(n1 * d2 - n2 * d1, d1 * d2)

    def mul(a, b):
        n1, d1 = a
        n2, d2 = b
        return normalize(n1 * n2, d1 * d2)

    def div(a, b):
        n1, d1 = a
        n2, d2 = b
        if n2 == 0:
            raise ZeroDivisionError("division by zero")
        return normalize(n1 * d2, d1 * n2)

    def power(a, exp):
        n, d = a
        if exp >= 0:
            return normalize(n ** exp, d ** exp)
        else:
            if n == 0:
                raise ZeroDivisionError("0 to negative power")
            return normalize(d ** (-exp), n ** (-exp))

    def parse_expr():
        left = parse_term()
        while True:
            op = peek()
            if op == '+':
                consume()
                right = parse_term()
                left = add(left, right)
            elif op == '-':
                consume()
                right = parse_term()
                left = sub(left, right)
            else:
