    else:
        return f"{result[0]}/{result[1]}"

import math

class Rational:
    """Simple rational number implementation."""
    __slots__ = ('num', 'den')

    def __init__(self, num: int, den: int = 1):
        if den == 0:
            raise ZeroDivisionError("Rational division by zero")
        if den < 0:
            num = -num
            den = -den
        g = math.gcd(num, den)
        self.num = num // g
        self.den = den // g

    def __str__(self) -> str:
        if self.den == 1:
            return str(self.num)
        return f"{self.num}/{self.den}"

    def __add__(self, other: 'Rational') -> 'Rational':
        return Rational(self.num * other.den + other.num * self.den, self.den * other.den)

    def __sub__(self, other: 'Rational') -> 'Rational':
        return Rational(self.num * other.den - other.num * self.den, self.den * other.den)

    def __mul__(self, other: 'Rational') -> 'Rational':
        return Rational(self.num * other.num, self.den * other.den)

    def __truediv__(self, other: 'Rational') -> 'Rational':
        if other.num == 0:
            raise ZeroDivisionError("Division by zero")
        return Rational(self.num * other.den, self.den * other.num)

    def __neg__(self) -> 'Rational':
        return Rational(-self.num, self.den)

    def is_integer(self) -> bool:
        return self.den == 1

    def get_int(self) -> int:
        if not self.is_integer():
            raise ValueError("Exponent must be an integer")
        return self.num

    def pow(self, exp: int) -> 'Rational':
        # Computes self^exp where exp is an integer
        if self.num == 0:
            if exp < 0:
                raise ZeroDivisionError("Zero to a negative power")
            # 0^0 = 1, 0^positive = 0
            return Rational(1, 1) if exp == 0 else Rational(0, 1)

        if exp == 0:
            return Rational(1, 1)

        if exp > 0:
            return Rational(self.num ** exp, self.den ** exp)
        else:
            # exp < 0
            # (n/d)^k = (d/(-k)) / (n/(-k))? No.
            # (n/d)^(-k) = (d/n)^k = d^k / n^k
            # Since n != 0 (checked above), this is safe.
            return Rational(self.den ** (-exp), self.num ** (-exp))


class Parser:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0

    def skip_spaces(self):
        while self.pos < len(self.text) and self.text[self.pos] == ' ':
            self.pos += 1

    def peek(self):
        self.skip_spaces()
        if self.pos < len(self.text):
            return self.text[self.pos]
        return None

    def advance(self):
        if self.pos < len(self.text):
            self.pos += 1
        else:
            raise ValueError("Unexpected end of input")

    def parse_expr(self) -> Rational:
        left = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.text[self.pos]
            self.advance()
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term(self) -> Rational:
        left = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.text[self.pos]
            self.advance()
            right = self.parse_unary()
            if op == '*':
                left = left * right
            else:
                left = left / right
        return left

    def parse_unary(self) -> Rational:
        if self.peek() == '-':
            self.advance()
            operand = self.parse_unary()
            return -operand
        else:
            return self.parse_power()

    def parse_power(self) -> Rational:
        base = self.parse_atom()
        if self.peek() == '^':
            self.advance()
            exp = self.parse_unary()
            if not exp.is_integer():
                raise ValueError("Exponent must be an integer")
            return base.pow(exp.get_int())
        return base

    def parse_atom(self) -> Rational:
        self.skip_spaces()
        if self.pos >= len(self.text):
            raise ValueError("Unexpected end of input")

        char = self.text[self.pos]

        if char.isdigit():
            return self.parse_int()
        elif char == '(':
            self.advance()
            val = self.parse_expr()
            self.skip_spaces()
            if self.pos >= len(self.text) or self.text[self.pos] != ')':
                raise ValueError("Missing closing parenthesis")
            self.advance()
            return val
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_int(self) -> Rational:
        start = self.pos
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            self.pos += 1
        if start == self.pos:
            raise ValueError("Expected integer")
        return Rational(int(self.text[start:self.pos]), 1)


def rational_eval(expr: str) -> str:
    if not expr:
        raise ValueError("Empty expression")
    parser = Parser(expr)
    result = parser.parse_expr()
    parser.skip_spaces()
    if parser.pos < len(parser.text):
        raise ValueError("Unexpected trailing characters")
    return str(result)

