    class Rational:
        __slots__ = ('n', 'd')
        def __init__(self, n, d=1):
            if d == 0:
                raise ZeroDivisionError("Rational denominator cannot be zero")
            if d < 0:
                n, d = -n, -d
            g = math.gcd(n, d)
            self.n = n // g
            self.d = d // g

        def __add__(self, other):
            return Rational(self.n * other.d + other.n * self.d, self.d * other.d)

        def __sub__(self, other):
            return Rational(self.n * other.d - other.n * self.d, self.d * other.d)

        def __mul__(self, other):
            return Rational(self.n * other.n, self.d * other.d)

        def __truediv__(self, other):
            if other.n == 0:
                raise ZeroDivisionError("Division by zero")
            return Rational(self.n * other.d, self.d * other.n)

        def __pow__(self, other):
            if other.d != 1:
                raise ValueError("Exponent must be an integer")
            k = other.n

            if self.n == 0 and k == 0:
                return Rational(1, 1)

            if self.n == 0:
                if k < 0:
                    raise ZeroDivisionError("0 to negative power")
                return Rational(0, 1)

            if k == 0:
                return Rational(1, 1)

            if k > 0:
                return Rational(self.n ** k, self.d ** k)
            else:
                return Rational(self.d ** (-k), self.n ** (-k))

        def __neg__(self):
            return Rational(-self.n, self.d)

        def __repr__(self):
            if self.d == 1:
                return str(self.n)
            return f"{self.n}/{self.d}"

    class Parser:
        def __init__(self, s):
            self.s = s
            self.i = 0
            self.n = len(s)

        def peek(self):
            if self.i < self.n:
                return self.s[self.i]
            return None

        def consume(self):
            if self.i < self.n:
                ch = self.s[self.i]
                self.i += 1
                return ch
            return None

        def skip_spaces(self):
            while self.i < self.n and self.s[self.i] == ' ':
                self.i += 1

        def error(self, msg="Malformed input"):
            raise ValueError(msg)

        def parse(self):
            self.skip_spaces()
            res = self.parse_expr()
            self.skip_spaces()
            if self.i < self.n:
                self.error()
            return res

        def parse_expr(self):
            left = self.parse_term()
            while True:
                self.skip_spaces()
                op = self.peek()
                if op == '+':
                    self.consume()
                    right = self.parse_term()
                    left = left + right
                elif op == '-':
                    self.consume()
                    right = self.parse_term()
                    left = left - right
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_unary()
            while True:
                self.skip_spaces()
                op = self.peek()
                if op == '*':
                    self.consume()
                    right = self.parse_unary()
                    left = left * right
                elif op == '/':
                    self.consume()
                    right = self.parse_unary()
                    left = left / right
                else:
                    break
            return left

        def parse_unary(self):
            self.skip_spaces()
            if self.peek() == '-':
                self.consume()
                val = self.parse_unary()
                return -val
            return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            self.skip_spaces()
            if self.peek() == '^':
                self.consume()
                exp = self.parse_unary()
                return base ** exp
            return base

        def parse_atom(self):
            self.skip_spaces()
            ch = self.peek()
            if ch == '(':
                self.consume()
                val = self.parse_expr()
                self.skip_spaces()
                if self.peek() != ')':
                    self.error("Expected ')'")
                self.consume()
                return val
            elif ch is not None and ch.isdigit():
                start = self.i
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
                num_str = self.s[start:self.i]
                return Rational(int(num_str))
            else:
                self.error(f"Unexpected character: {ch}")

    parser = Parser(expr)
    result = parser.parse()
    return result.__repr__()

import math

def rational_eval(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    s = expr
    n = len(s)

    while i < n:
        if s[i].isspace():
            i += 1
            continue
        if s[i].isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(('INT', int(s[i:j])))
            i = j
        elif s[i] == '+':
            tokens.append(('PLUS', None))
            i += 1
        elif s[i] == '-':
            tokens.append(('MINUS', None))
            i += 1
        elif s[i] == '*':
            tokens.append(('MUL', None))
            i += 1
        elif s[i] == '/':
            tokens.append(('DIV', None))
            i += 1
        elif s[i] == '^':
            tokens.append(('POW', None))
            i += 1
        elif s[i] == '(':
            tokens.append(('LPAREN', None))
            i += 1
        elif s[i] == ')':
            tokens.append(('RPAREN', None))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {s[i]}")
    tokens.append(('EOF', None))

    pos = 0

    def peek():
        return tokens[pos]

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def match(ttype):
        tok = peek()
        if tok[0] == ttype:
            return consume()
        return None

    def parse_expr():
        # expr := term (('+' | '-') term)*
        res = parse_term()
        while True:
            op = match('PLUS')
            if op:
                rhs = parse_term()
                res = add_rational(res, rhs)
                continue
            op = match('MINUS')
            if op:
                rhs = parse_term()
                res = sub_rational(res, rhs)
                continue
            break
        return res

    def parse_term():
        # term := unary (('*' | '/') unary)*
        res = parse_unary()
        while True:
            op = match('MUL')
            if op:
                rhs = parse_unary()
                res = mul_rational(res, rhs)
                continue
            op = match('DIV')
            if op:
                rhs = parse_unary()
                res = div_rational(res, rhs)
                continue
            break
        return res

    def parse_unary():
        # unary := '-' unary | power
        if match('MINUS'):
            operand = parse_unary()
            return neg_rational(operand)
        return parse_power()

    def parse_power():
        # power := atom ('^' unary)?
        base = parse_atom()
        if match('POW'):
            exp = parse_unary()
            # Exponent must be integer
            if exp[1] != 1:
                raise ValueError("Exponent must be an integer")
            exp_val = exp[0]
            res = pow_rational(base, exp_val)
            return res
        return base

    def parse_atom():
        # atom := INT | '(' expr ')'
        tok = peek()
        if tok[0] == 'INT':
            consume()
            return (tok[1], 1)
        elif tok[0] == 'LPAREN':
            consume()
            res = parse_expr()
            if not match('RPAREN'):
                raise ValueError("Missing closing parenthesis")
            return res
        else:
            raise ValueError("Unexpected token in atom")

    # Rational arithmetic helpers
    def gcd(a, b):
        return math.gcd(a, b)

    def normalize(n, d):
        if d == 0:
            raise ZeroDivisionError("Division by zero")
        if d < 0:
            n = -n
            d = -d
        g = gcd(abs(n), d)
        return (n // g, d // g)

    def add_rational(a, b):
        n = a[0] * b[1] + b[0] * a[1]
        d = a[1] * b[1]
        return normalize(n, d)

    def sub_rational(a, b):
        n = a[0] * b[1] - b[0] * a[1]
        d = a[1] * b[1]
        return normalize(n, d)

    def mul_rational(a, b):
        n = a[0] * b[0]
        d = a[1] * b[1]
        return normalize(n, d)

    def div_rational(a, b):
        if b[0] == 0:
            raise ZeroDivisionError("Division by zero")
        n = a[0] * b[1]
        d = a[1] * b[0]
        return normalize(n, d)

    def neg_rational(a):
        return (-a[0], a[1])

    def pow_rational(base, exp):
        b_n, b_d = base
        if b_n == 0:
            if exp < 0:
                raise ZeroDivisionError("0 to a negative power")
            if exp == 0:
                return (1, 1)
            return (0, 1)

        if exp >= 0:
            num = b_n ** exp
            den = b_d ** exp
            return normalize(num, den)
        else:
            # exp < 0
            pos_exp = -exp
            num = b_d ** pos_exp
            den = b_n ** pos_exp
            return normalize(num, den)

    result = parse_expr()

    # Check if all tokens consumed
    if peek()[0] != 'EOF':
        raise ValueError("Unexpected token at end of expression")

    n, d = result
    if d == 1:
        return str(n)
    else:
        return f"{n}/{d}"

import math

class Rational:
    def __init__(self, num, den=1):
        if den == 0:
            raise ZeroDivisionError("Denominator is zero")
        if den < 0:
            num = -num
            den = -den
        common = math.gcd(abs(num), den)
        self.num = num // common
        self.den = den // common

    def __add__(self, other):
        b, d = self.den, other.den
        g = math.gcd(b, d)
        lcm = (b // g) * d
        num = self.num * (lcm // b) + other.num * (lcm // d)
        return Rational(num, lcm)

    def __sub__(self, other):
        return self + Rational(-other.num, other.den)

    def __mul__(self, other):
        return Rational(self.num * other.num, self.den * other.den)

    def __truediv__(self, other):
        if other.num == 0:
            raise ZeroDivisionError("Division by zero")
        return Rational(self.num * other.den, self.den * other.num)

    def __pow__(self, exp):
        if not isinstance(exp, int):
            if hasattr(exp, 'den') and exp.den != 1:
                raise ValueError("Exponent must be an integer")
            if hasattr(exp, 'num'):
                exp = exp.num
            else:
                raise ValueError("Exponent must be an integer")

        if self.num == 0:
            if exp == 0:
                return Rational(1, 1)
            elif exp < 0:
                raise ZeroDivisionError("0 to a negative power")
            else:
                return Rational(0, 1)

        if exp < 0:
            base = Rational(self.den, self.num)
            return base ** (-exp)

        n_res = pow(self.num, exp)
        d_res = pow(self.den, exp)
        return Rational(n_res, d_res)

    def __str__(self):
        if self.den == 1:
            return str(self.num)
        return f"{self.num}/{self.den}"

