            if self.peek() == '-':
                self.consume()
                return -self.unary()
            return self.power()

        def power(self):
            base = self.atom()
            if self.peek() == '^':
                self.consume()
                exp = self.unary()
                if exp.denominator != 1:
                    raise ValueError("Exponent must be an integer")
                exp = int(exp)
                if base == 0 and exp < 0:
                    raise ZeroDivisionError("0 to a negative power")
                return base ** exp
            return base

        def atom(self):
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of input")
            if token == '(':
                self.consume()
                res = self.expr()
                if self.peek() != ')':
                    raise ValueError("Missing closing parenthesis")
                self.consume()
                return res
            elif isinstance(token, int):
                self.consume()
                return Fraction(token)
            else:
                raise ValueError(f"Unexpected token: {token}")

    if not expr.strip():
        raise ValueError("Empty input")

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty input")

    parser = Parser(tokens)
    result = parser.parse()

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

from fractions import Fraction

def rational_eval(expr: str) -> str:
    def tokenize(s: str):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
            elif s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j])))
                i = j
            elif s[i] in '+-*/^()':
                tokens.append(('OP', s[i]))
                i += 1
            else:
                raise ValueError("Malformed input")
        tokens.append(('EOF', None))
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos]

        def advance(self):
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok

        def expect(self, ttype, tval=None):
            tok = self.peek()
            if tok[0] != ttype or (tval is not None and tok[1] != tval):
                raise ValueError("Malformed input")
            return self.advance()

        def parse_expr(self):
            val = self.parse_term()
            while self.peek()[0] == 'OP' and self.peek()[1] in '+-':
                op = self.advance()[1]
                rhs = self.parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            return val

        def parse_term(self):
            val = self.parse_unary()
            while self.peek()[0] == 'OP' and self.peek()[1] in '*/':
                op = self.advance()[1]
                rhs = self.parse_unary()
                if op == '*':
                    val *= rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("Division by zero")
                    val /= rhs
            return val

        def parse_unary(self):
            if self.peek()[0] == 'OP' and self.peek()[1] == '-':
                self.advance()
                return -self.parse_unary()
            return self.parse_power()

        def parse_power(self):
            base = self.parse_atom()
            if self.peek()[0] == 'OP' and self.peek()[1] == '^':
                self.advance()
                exp = self.parse_unary()
                if exp.denominator != 1:
                    raise ValueError("Exponent must be an integer")
                exp_int = exp.numerator
                if base == 0:
                    if exp_int == 0:
                        return Fraction(1)
                    elif exp_int < 0:
                        raise ZeroDivisionError("0 to a negative power")
                return base ** exp_int
            return base

        def parse_atom(self):
            tok = self.peek()
            if tok[0] == 'INT':
                self.advance()
                return Fraction(tok[1])
            elif tok[0] == 'OP' and tok[1] == '(':
                self.advance()
                val = self.parse_expr()
                self.expect('OP', ')')
                return val
            else:
                raise ValueError("Malformed input")

    tokens = tokenize(expr)
    parser = Parser(tokens)
    result = parser.parse_expr()
    if parser.pos != len(tokens) - 1:
        raise ValueError("Malformed input")
    return str(result)

from fractions import Fraction

def rational_eval(expr: str) -> str:
    s = expr
    n = len(s)
    i = 0

    def skip_spaces():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def consume(expected=None):
        nonlocal i
        skip_spaces()
        if expected is not None:
            if i >= n or s[i] != expected:
                raise ValueError(f"Expected '{expected}' but got '{s[i] if i < n else 'EOF'}'")
            i += 1
        else:
            if i >= n:
                raise ValueError("Unexpected end of input")
            ch = s[i]
            i += 1
            return ch

    def parse_int():
        nonlocal i
        skip_spaces()
        if i >= n or not s[i].isdigit():
            raise ValueError("Expected integer")
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    def parse_atom():
        skip_spaces()
        if i >= n:
            raise ValueError("Unexpected end of input")
        ch = s[i]
        if ch == '(':
            consume('(')
            val = parse_expr()
            consume(')')
            return val
        elif ch.isdigit():
            return Fraction(parse_int())
        else:
            raise ValueError(f"Unexpected character: {ch}")

    def parse_power():
        base = parse_atom()
        skip_spaces()
        if i < n and s[i] == '^':
            consume('^')
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
            exp_int = exp.numerator
            if base == 0:
                if exp_int < 0:
                    raise ZeroDivisionError("0 to a negative power")
                elif exp_int == 0:
                    return Fraction(1)
                else:
                    return Fraction(0)
            return base ** exp_int
        return base

    def parse_unary():
        skip_spaces()
        if i < n and s[i] == '-':
            consume('-')
            return -parse_unary()
        return parse_power()

    def parse_term():
        left = parse_unary()
        while True:
            skip_spaces()
            if i < n and s[i] in ('*', '/'):
                op = consume()
                right = parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_expr():
        left = parse_term()
        while True:
            skip_spaces()
            if i < n and s[i] in ('+', '-'):
                op = consume()
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    result = parse_expr()
    skip_spaces()
    if i < n:
        raise ValueError("Unexpected trailing characters")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        # Fraction normalizes sign to numerator, denominator is always positive
        return f"{result.numerator}/{result.denominator}"

import heapq

def skyline(buildings: list[list[int]]) -> list[list[int]]:
    if not buildings:
        return []

    events = []
    for l, r, h in buildings:
        events.append((l, -h, r))
        events.append((r, 0, r))
    events.sort()

    skyline = []
    heap = [(0, float('inf'))]

    for x, neg_h, r in events:
        if neg_h != 0:
            heapq.heappush(heap, (neg_h, r))
        while heap[0][1] <= x:
            heapq.heappop(heap)
        h = -heap[0][0]
        if not skyline or skyline[-1][1] != h:
            skyline.append([x, h])

    return skyline

