def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""

    m = len(t)
    n = len(s)
    if n < m:
        return ""

    # dp[k] stores the largest starting index i such that t[:k] is a subsequence of s[i:current_j+1]
    # dp[0] is always 0 (empty prefix starts at 0)
    dp = [-1] * (m + 1)
    dp[0] = 0

    min_len = n + 1
    best_start = -1

    # Pre-convert t to list for slightly faster indexing
    t_chars = list(t)

    for j, char_s in enumerate(s):
        # Iterate backwards to avoid using updated dp values from the current position
        for k in range(m, 0, -1):
            if char_s == t_chars[k - 1]:
                if k == 1:
                    dp[1] = j
                elif dp[k - 1] != -1:
                    if dp[k - 1] > dp[k]:
                        dp[k] = dp[k - 1]

        if dp[m] != -1:
            length = j - dp[m] + 1
            if length < min_len:
                min_len = length
                best_start = dp[m]

    if best_start == -1:
        return ""
    return s[best_start:best_start + min_len]

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""

    m = len(t)
    # dp[k] stores the earliest starting index in s such that t[:k+1] 
    # is a subsequence of s[dp[k] ... current_i]
    dp = [-1] * m

    best_len = float('inf')
    best_start = -1
    best_end = -1

    for i, char in enumerate(s):
        # Update dp in reverse to avoid using the same character s[i] 
        # for multiple positions in t within the same step.
        for k in range(m - 1, -1, -1):
            if char == t[k]:
                if k == 0:
                    dp[0] = i
                elif dp[k - 1] != -1:
                    dp[k] = dp[k - 1]

        # If the full t is matched ending at i, check window length
        if dp[m - 1] != -1:
            curr_len = i - dp[m - 1] + 1
            if curr_len < best_len:
                best_len = curr_len
                best_start = dp[m - 1]
                best_end = i

    if best_len == float('inf'):
        return ""
    return s[best_start:best_end + 1]

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""

    n, m = len(s), len(t)
    best_len = n + 1
    best_start = -1
    best_end = -1

    for i in range(n):
        if s[i] != t[0]:
            continue

        # Forward pass: find the earliest end index j such that t is a subsequence of s[i:j]
        j, k = i, 0
        while j < n and k < m:
            if s[j] == t[k]:
                k += 1
            j += 1

        if k == m:
            # Backward pass: shrink from the right to find the latest possible start
            end = j - 1
            k = m - 1
            while end >= i and k >= 0:
                if s[end] == t[k]:
                    k -= 1
                end -= 1
            start = end + 1
            length = j - start

            if length < best_len:
                best_len = length
                best_start = start
                best_end = j - 1

    if best_start == -1:
        return ""
    return s[best_start:best_end + 1]

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""
    n = len(s)
    m = len(t)
    if n < m:
        return ""

    # next_match[k] will store the smallest index j such that s[i:j] contains t[k:]
    # Initialize with n (sentinel for "not found")
    next_match = [n] * (m + 1)

    best_len = n + 1
    best_start = -1

    # Process s backwards to maintain O(m) space
    for i in range(n - 1, -1, -1):
        # Update next_match for each position in t
        # We iterate k from 0 to m-1. If s[i] matches t[k], 
        # we can potentially start matching t[k:] at i, ending at next_match[k+1].
        # We keep the minimum of the old value (match starting later) and new value.
        for k in range(m):
            if s[i] == t[k]:
                end = next_match[k + 1]
                if end < next_match[k]:
                    next_match[k] = end

        # next_match[0] now holds the smallest end index for a window starting at i
        end = next_match[0]
        if end != n:
            length = end - i
            if length < best_len:
                best_len = length
                best_start = i
                # Cannot get shorter than len(t)
                if best_len == m:
                    return s[best_start:best_start + best_len]

    if best_start == -1:
        return ""
    return s[best_start:best_start + best_len]

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""
    n = len(s)
    m = len(t)
    if n < m:
        return ""

    # Precompute next occurrence for each distinct character in t
    chars_in_t = set(t)
    nxt = {}
    for c in chars_in_t:
        arr = [n] * (n + 1)
        for i in range(n - 1, -1, -1):
            arr[i] = i if s[i] == c else arr[i + 1]
        nxt[c] = arr

    min_len = n + 1
    best_start = -1

    for i in range(n):
        # Optimization: remaining substring cannot be shorter than current best
        if n - i < min_len:
            break

        curr = i
        valid = True
        end = -1
        for c in t:
            curr = nxt[c][curr]
            if curr == n:
                valid = False
                break
            end = curr
            curr += 1  # Ensure strictly increasing indices for subsequence

        if valid:
            length = end - i + 1
            if length < min_len:
                min_len = length
                best_start = i
                # Cannot find a shorter valid window than t itself
                if min_len == m:
                    return s[i:end + 1]

    return s[best_start:best_start + min_len] if best_start != -1 else ""

def min_window_subseq(s: str, t: str) -> str:
    if not t:
        return ""
    n, m = len(s), len(t)
    if n < m:
        return ""

    # dp[j] stores the starting index of the shortest window in s[0..i]
    # that contains t[0..j] as a subsequence and ends at or before i.
    dp = [-1] * m
    min_len = n + 1
    best_start = -1

    for i in range(n):
        # Iterate backwards to use dp values from the previous iteration (i-1)
        for j in range(m - 1, -1, -1):
            if s[i] == t[j]:
                if j == 0:
                    dp[j] = i
                elif dp[j - 1] != -1:
                    dp[j] = dp[j - 1]

        if dp[m - 1] != -1:
            curr_len = i - dp[m - 1] + 1
            if curr_len < min_len:
                min_len = curr_len
                best_start = dp[m - 1]
                # Cannot get shorter than t itself
                if min_len == m:
                    break

    if best_start == -1:
        return ""
    return s[best_start:best_start + min_len]

import itertools
from typing import Tuple, Set, Dict, List

def bool_equiv(a: str, b: str) -> bool:
    def tokenize(s: str) -> List[Tuple[str, str]]:
        tokens = []
        i, n = 0, len(s)
        while i < n:
            if s[i].isspace():
                i += 1
                continue
            if s[i:i+3] == '<->':
                tokens.append(('EQUIV', '<->')); i += 3
            elif s[i:i+2] == '->':
                tokens.append(('IMP', '->')); i += 2
            elif s[i] == '!':
                tokens.append(('NOT', '!')); i += 1
            elif s[i] == '&':
                tokens.append(('AND', '&')); i += 1
            elif s[i] == '|':
                tokens.append(('OR', '|')); i += 1
            elif s[i] == '(':
                tokens.append(('LPAREN', '(')); i += 1
            elif s[i] == ')':
                tokens.append(('RPAREN', ')')); i += 1
            elif s[i].islower():
                j = i
                while j < n and s[j].islower():
                    j += 1
                tokens.append(('VAR', s[i:j])); i = j
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        if not tokens:
            raise ValueError("Empty formula")
        return tokens

    class Parser:
        def __init__(self, tokens: List[Tuple[str, str]]):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def consume(self, expected_type: str = None):
            t = self.peek()
            if t is None:
                raise ValueError("Unexpected end of input")
            if expected_type and t[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {t[0]}")
            self.pos += 1
            return t

        def parse(self):
            node = self.parse_equiv()
            if self.pos < len(self.tokens):
                raise ValueError("Unexpected tokens after formula")
            return node

        def parse_equiv(self):
            left = self.parse_imp()
            while self.peek() and self.peek()[0] == 'EQUIV':
                self.consume()
                right = self.parse_imp()
                left = ('EQUIV', left, right)
            return left

        def parse_imp(self):
            left = self.parse_or()
            if self.peek() and self.peek()[0] == 'IMP':
                self.consume()
                right = self.parse_imp()
                return ('IMP', left, right)
            return left

        def parse_or(self):
            left = self.parse_and()
            while self.peek() and self.peek()[0] == 'OR':
                self.consume()
                right = self.parse_and()
                left = ('OR', left, right)
            return left

        def parse_and(self):
            left = self.parse_not()
            while self.peek() and self.peek()[0] == 'AND':
                self.consume()
                right = self.parse_not()
                left = ('AND', left, right)
            return left

        def parse_not(self):
            if self.peek() and self.peek()[0] == 'NOT':
                self.consume()
                return ('NOT', self.parse_not())
            return self.parse_primary()

        def parse_primary(self):
            t = self.peek()
            if t is None:
                raise ValueError("Unexpected end of input")
            if t[0] == 'LPAREN':
                self.consume()
                node = self.parse_equiv()
                self.consume('RPAREN')
                return node
            elif t[0] == 'VAR':
                self.consume()
                return ('VAR', t[1])
            else:
                raise ValueError(f"Unexpected token: {t[0]}")

    def get_vars(node) -> Set[str]:
        t = node[0]
        if t == 'VAR':
            return {node[1]}
        elif t == 'NOT':
            return get_vars(node[1])
        else:
            return get_vars(node[0]) | get_vars(node[1])

    def eval_node(node, assignments: Dict[str, bool]) -> bool:
        t = node[0]
        if t == 'VAR':
            return assignments[node[1]]
        elif t == 'NOT':
            return not eval_node(node[1], assignments)
        elif t == 'AND':
            return eval_node(node[0], assignments) and eval_node(node[1], assignments)
        elif t == 'OR':
            return eval_node(node[0], assignments) or eval_node(node[1], assignments)
        elif t == 'IMP':
            return (not eval_node(node[0], assignments)) or eval_node(node[1], assignments)
        elif t == 'EQUIV':
            return eval_node(node[0], assignments) == eval_node(node[1], assignments)
        return False

    try:
        tokens_a = tokenize(a)
        tokens_b = tokenize(b)
        parser_a = Parser(tokens_a)
        parser_b = Parser(tokens_b)
        ast_a = parser_a.parse()
        ast_b = parser_b.parse()
    except ValueError:
        raise

    all_vars = get_vars(ast_a) | get_vars(ast_b)
    var_list = sorted(all_vars)
    n = len(var_list)

    for vals in itertools.product((False, True), repeat=n):
        assignments = dict(zip(var_list, vals))
        if eval_node(ast_a, assignments) != eval_node(ast_b, assignments):
            return False
    return True

def tokenize(s: str) -> list:
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isspace():
            i += 1
            continue
        if s[i] in '!&|()':
            tokens.append(s[i])
            i += 1
        elif i + 3 <= n and s[i:i+3] == '<->':
            tokens.append('<->')
            i += 3
        elif i + 2 <= n and s[i:i+2] == '->':
            tokens.append('->')
            i += 2
        elif s[i].islower():
            j = i
            while j < n and s[j].islower():
                j += 1
            tokens.append(s[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {s[i]}")
    return tokens

class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def parse_expr(self):
        left, self.pos = self.parse_term()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '<->':
            self.pos += 1
            right, self.pos = self.parse_term()
            left = ('<->', left, right)
        return left

    def parse_term(self):
        left, self.pos = self.parse_or()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '->':
            self.pos += 1
            right, self.pos = self.parse_term()
            left = ('->', left, right)
        return left

    def parse_or(self):
        left, self.pos = self.parse_and()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '|':
            self.pos += 1
            right, self.pos = self.parse_and()
            left = ('|', left, right)
        return left

    def parse_and(self):
        left, self.pos = self.parse_not()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '&':
            self.pos += 1
            right, self.pos = self.parse_not()
            left = ('&', left, right)
        return left

    def parse_not(self):
        if self.pos < len(self.tokens) and self.tokens[self.pos] == '!':
            self.pos += 1
            operand, self.pos = self.parse_not()
            return ('!', operand), self.pos
        return self.parse_primary()

    def parse_primary(self):
        if self.pos >= len(self.tokens):
            raise ValueError("Unexpected end of expression")
