    all_vars = sorted(vars_a | vars_b)

    n = len(all_vars)
    for i in range(1 << n):
        assignment = {all_vars[j]: bool(i & (1 << j)) for j in range(n)}
        if evaluate(ast_a, assignment) != evaluate(ast_b, assignment):
            return False
    return True

def count_digit(n: int, d: int) -> int:
    if n < 0:
        return 0

    count = 0
    base = 1

    while base <= n:
        high = n // (base * 10)
        cur = (n // base) % 10
        low = n % base

        if d == 0:
            # For digit 0, we skip the leading zero case.
            # high represents full blocks of size 10^(k+1).
            # The first block (0 to 10^k - 1) corresponds to leading zeros, so we use (high - 1).
            if high > 0:
                count += (high - 1) * base
                if cur == 0:
                    count += low + 1
                elif cur > 0:
                    count += base
        else:
            count += high * base
            if cur == d:
                count += low + 1
            elif cur > d:
                count += base

        base *= 10

    # The number 0 itself contributes one '0'
    if d == 0:
        count += 1

    return count

def count_digit(n: int, d: int) -> int:
    count = 0
