    while p <= n:
        divider = p * 10
        higher = n // divider
        current = (n // p) % 10
        lower = n % p
        if d == 0:
            higher -= 1
        count += higher * p
        if current == d:
            count += lower + 1
        elif current > d:
            count += p
        p *= 10
    if d == 0:
        count += 1
    return count

