def count_digit(n: int, d: int) -> int:
    if n < 0:
        return 0
    count = 0
    factor = 1
    while factor <= n:
        higher = n // (factor * 10)
        current = (n // factor) % 10
        lower = n % factor

        if d == 0:
            if current == 0:
                count += (higher - 1) * factor + lower + 1
            else:
                count += higher * factor
        else:
            if current > d:
                count += (higher + 1) * factor
            elif current == d:
                count += higher * factor + lower + 1
            else:
                count += higher * factor

        factor *= 10

    if d == 0:
        count += 1  # Account for the number "0" itself
    return count

import math

def fraction_to_base(p: int, q: int, b: int) -> str:
    if q == 0:
        raise ValueError("q cannot be 0")

    if p == 0:
        return "0"

    neg = (p < 0) ^ (q < 0)
    p, q = abs(p), abs(q)

    # Simplify fraction to ensure shortest representation
    g = math.gcd(p, q)
    p //= g
    q //= g

    int_part = p // q
    rem = p % q

    def int_to_base(n: int, base: int) -> str:
        if n == 0:
            return "0"
        digits = "0123456789abcdefghijklmnopqrstuvwxyz"
        res = []
        while n > 0:
            res.append(digits[n % base])
            n //= base
        return "".join(reversed(res))

    int_str = int_to_base(int_part, b)

    if rem == 0:
        return ("-" + int_str) if neg else int_str

    frac_digits = []
    seen = {}
    while rem != 0:
        if rem in seen:
            non_rep = frac_digits[:seen[rem]]
            rep = frac_digits[seen[rem]:]
            break
        seen[rem] = len(frac_digits)
        rem, digit = divmod(rem * b, q)
        frac_digits.append(digit)
    else:
        non_rep = frac_digits
        rep = []

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    non_rep_str = "".join(digits[d] for d in non_rep)
    rep_str = "".join(digits[d] for d in rep)

    if rep_str:
        frac_str = non_rep_str + "(" + rep_str + ")"
    elif non_rep_str:
        frac_str = non_rep_str
    else:
        frac_str = ""

    res = int_str + frac_str
    return ("-" + res) if neg else res
